window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2020-3"]={"track":"written","round":"2020-3","questions":[{"id":"written-2020-3-1","no":1,"unit":"소프트웨어 설계","q":"요구사항 분석 시에 필요한 기술로 가장 거리가 먼 것은?","choices":["청취와 인터뷰 질문 기술","분석과 중재기술","설계 및 코딩 기술","관찰 및 모델 작성 기술"],"ans":3,"rate":78,"wiki":[{"title":"요구사항 분석","url":"https://itwiki.kr/w/요구사항 분석"}],"exp":{"concept":"요구사항 분석은 사용자가 원하는 것이 무엇인지 알아내고 정리하는 단계다. 그래서 사람의 말을 듣고 묻는 기술, 서로 다른 의견을 분석하고 조정하는 기술, 업무를 관찰해 모델로 그려 내는 기술이 필요하다. 무엇을 만들지 정하는 단계이므로 어떻게 만들지(설계·코딩)는 아직 다루지 않는다.","choices":[{"verdict":"오답","why":"사용자에게서 요구를 끌어내려면 잘 듣고 질문하는 인터뷰 기술이 꼭 필요하다."},{"verdict":"오답","why":"이해관계자마다 요구가 다르거나 충돌하므로 이를 분석하고 중재하는 기술이 필요하다."},{"verdict":"정답","why":"설계와 코딩은 요구사항이 확정된 뒤 설계·구현 단계에서 쓰는 기술이라 요구사항 분석 기술과 거리가 멀다."},{"verdict":"오답","why":"현재 업무를 관찰하고 그 결과를 모델(다이어그램 등)로 표현하는 것은 요구사항 분석의 핵심 활동이다."}],"keywords":[{"term":"요구사항 분석","desc":"사용자 요구를 수집·분석해 개발할 기능과 제약을 명확히 정하는 단계"},{"term":"요구사항 분석 기술","desc":"청취와 인터뷰 질문, 분석과 중재, 관찰 및 모델 작성 기술"}],"memo":"요구사항 분석은 무엇을(What) 만들지 정하는 단계, 설계·코딩은 어떻게(How) 만들지 정하는 단계로 나눠 기억한다."}},{"id":"written-2020-3-2","no":2,"unit":"소프트웨어 설계","q":"다음 내용이 설명하는 디자인 패턴은?\n<img src=\"data/img/eip_written_20200822_002.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Visitor패턴","Observer패턴","Factory Method 패턴","Bridge 패턴"],"ans":3,"rate":63,"wiki":[{"title":"GoF 디자인 패턴","url":"https://itwiki.kr/w/GoF 디자인 패턴"}],"exp":{"concept":"디자인 패턴 중 생성 패턴은 객체를 만드는 방법을 정리한 것이다. 팩토리 메서드(Factory Method) 패턴은 상위 클래스가 객체 생성용 인터페이스(메서드)만 정해 두고, 실제로 어떤 클래스의 인스턴스를 만들지는 서브클래스가 결정하게 한다. 생성자 역할을 서브클래스에 맡긴다는 뜻에서 가상 생성자(Virtual-Constructor) 패턴이라고도 부른다.","choices":[{"verdict":"오답","why":"방문자(Visitor) 패턴은 행위 패턴으로, 데이터 구조는 그대로 두고 처리 기능을 별도 방문자 클래스로 분리해 구조를 돌아다니며 작업하게 한다."},{"verdict":"오답","why":"옵서버(Observer) 패턴은 행위 패턴으로, 한 객체의 상태가 바뀌면 의존하는 객체들에 자동으로 알려 주는 구조다."},{"verdict":"정답","why":"객체 생성 인터페이스는 상위에서 정의하고 어떤 클래스를 인스턴스화할지는 서브클래스가 결정하며, Virtual-Constructor라고도 하는 생성 패턴이다."},{"verdict":"오답","why":"브리지(Bridge) 패턴은 구조 패턴으로, 기능(추상화) 계층과 구현 계층을 분리해 각각 독립적으로 확장할 수 있게 한다."}],"keywords":[{"term":"Factory Method","desc":"객체 생성을 서브클래스에 위임하는 생성 패턴, 가상 생성자 패턴"},{"term":"생성 패턴","desc":"Abstract Factory, Builder, Factory Method, Prototype, Singleton"},{"term":"Bridge","desc":"구현부와 추상화 계층을 분리하는 구조 패턴"}],"memo":"'서브클래스가 어떤 객체를 만들지 결정' 또는 'Virtual-Constructor'라는 말이 보이면 바로 Factory Method다."}},{"id":"written-2020-3-3","no":3,"unit":"소프트웨어 설계","q":"럼바우 객체 지향 분석과 거리가 먼 것은?","choices":["기능 모델링","동적 모델링","객체 모델링","정적 모델링"],"ans":4,"rate":84,"exp":{"concept":"럼바우(Rumbaugh)의 객체 지향 분석 기법(OMT)은 시스템을 세 가지 관점으로 나누어 모델링한다. 객체 모델링은 객체와 관계를, 동적 모델링은 시간에 따른 상태 변화를, 기능 모델링은 데이터 흐름에 따른 처리 과정을 그린다. 분석 순서는 객체 → 동적 → 기능이다.","choices":[{"verdict":"오답","why":"기능 모델링은 자료 흐름도(DFD)로 입력이 어떤 처리를 거쳐 출력되는지 표현하는 럼바우 기법의 한 단계다."},{"verdict":"오답","why":"동적 모델링은 상태 다이어그램으로 객체의 상태 변화와 제어 흐름을 표현하는 럼바우 기법의 한 단계다."},{"verdict":"오답","why":"객체 모델링은 객체 다이어그램으로 객체와 속성, 객체 간 관계를 표현하는 럼바우 기법의 첫 단계다."},{"verdict":"정답","why":"럼바우 기법은 객체·동적·기능 세 모델링으로 이루어지며 정적 모델링이라는 단계는 없다."}],"keywords":[{"term":"럼바우 OMT","desc":"객체(Object) → 동적(Dynamic) → 기능(Functional) 모델링 순서의 객체 지향 분석 기법"},{"term":"동적 모델링","desc":"상태 다이어그램으로 시간에 따른 객체의 상태 변화를 표현"},{"term":"기능 모델링","desc":"자료 흐름도(DFD)로 데이터 처리 과정을 표현"}],"memo":"럼바우는 '객동기'(객체·동적·기능) 순서로 외운다. 동적이 있으니 정적은 함정이다."}},{"id":"written-2020-3-4","no":4,"unit":"소프트웨어 설계","q":"애자일 기법에 대한 설명으로 맞지 않은 것은?","choices":["절차와 도구보다 개인과 소통을 중요하게 생각한다.","계획에 중점을 두어 변경 대응이 난해하다.","소프트웨어가 잘 실행되는데 가치를 둔다.","고객과의 피드백을 중요하게 생각한다."],"ans":2,"rate":85,"wiki":[{"title":"애자일 방법론","url":"https://itwiki.kr/w/애자일 방법론"}],"exp":{"concept":"애자일(Agile)은 변화에 빠르게 대응하기 위해 짧은 주기로 개발하고 고객과 자주 소통하는 개발 방식이다. 애자일 선언문은 프로세스와 도구보다 개인과 상호작용을, 포괄적인 문서보다 작동하는 소프트웨어를, 계약 협상보다 고객과의 협력을, 계획을 따르기보다 변화에 대응하기를 더 가치 있게 여긴다.","choices":[{"verdict":"오답","why":"애자일 선언문의 첫 가치인 '프로세스와 도구보다 개인과 상호작용'에 해당하는 맞는 설명이다."},{"verdict":"정답","why":"애자일은 계획을 따르기보다 변화에 대응하는 것을 중시하므로, 계획 중심이라 변경 대응이 어렵다는 설명은 반대다. 이는 폭포수 모형 같은 전통적 방식의 특징이다."},{"verdict":"오답","why":"'포괄적인 문서보다 작동하는 소프트웨어'를 중시한다는 애자일 가치에 맞는 설명이다."},{"verdict":"오답","why":"'계약 협상보다 고객과의 협력'을 중시하므로 고객 피드백을 중요하게 생각한다는 설명은 맞다."}],"keywords":[{"term":"애자일 선언문 4가지 가치","desc":"개인과 상호작용, 작동하는 소프트웨어, 고객과의 협력, 변화에 대응"},{"term":"애자일 방법론 예","desc":"XP(eXtreme Programming), 스크럼(Scrum), 칸반(Kanban), 린(Lean) 등"}],"memo":"애자일(agile)은 '민첩한'이라는 뜻이다. 계획 고수·변경 곤란이 보이면 애자일이 아니다."}},{"id":"written-2020-3-5","no":5,"unit":"소프트웨어 설계","q":"미들웨어 솔루션의 유형에 포함되지 않는 것은?","choices":["WAS","Web Server","RPC","ORB"],"ans":2,"rate":61,"exp":{"concept":"미들웨어(Middleware)는 운영체제와 응용 프로그램 사이, 또는 서로 다른 시스템 사이에서 통신과 데이터 교환을 중개하는 소프트웨어다. 대표 유형으로 DB 미들웨어, RPC, MOM, TP-Monitor, ORB, WAS가 있다. 웹 서버는 정적 콘텐츠를 제공하는 서버 프로그램이라 미들웨어 유형으로 분류하지 않는다.","choices":[{"verdict":"오답","why":"WAS(Web Application Server)는 동적 콘텐츠를 처리하기 위한 미들웨어로, 미들웨어 유형에 포함된다."},{"verdict":"정답","why":"웹 서버(Web Server)는 HTML·이미지 같은 정적 콘텐츠를 클라이언트에 전달하는 서버로, 미들웨어 솔루션 유형에 포함되지 않는다."},{"verdict":"오답","why":"RPC(Remote Procedure Call)는 원격 프로시저를 로컬 프로시저처럼 호출하게 해 주는 미들웨어다."},{"verdict":"오답","why":"ORB(Object Request Broker)는 네트워크상의 객체 간 요청과 응답을 중개하는 객체 지향 미들웨어로, CORBA 표준의 핵심이다."}],"keywords":[{"term":"미들웨어 유형","desc":"DB, RPC, MOM, TP-Monitor, ORB, WAS"},{"term":"MOM","desc":"Message Oriented Middleware, 메시지 기반 비동기 통신 미들웨어"},{"term":"WAS","desc":"Web Application Server, 동적 웹 콘텐츠 처리용 미들웨어(예: Tomcat)"}],"memo":"WAS와 Web Server를 헷갈리지 말 것. 동적 처리를 하는 WAS만 미들웨어 유형이다."}},{"id":"written-2020-3-6","no":6,"unit":"소프트웨어 설계","q":"UML에서 시퀀스 다이어그램의 구성 항목에 해당하지 않는 것은?","choices":["생명선","실행","확장","메시지"],"ans":3,"rate":56,"wiki":[{"title":"시퀀스 다이어그램","url":"https://itwiki.kr/w/시퀀스 다이어그램"}],"exp":{"concept":"시퀀스 다이어그램은 객체들이 시간 순서에 따라 메시지를 주고받는 모습을 표현하는 UML 행위 다이어그램이다. 구성 요소는 액터, 객체, 생명선, 실행(활성 상자), 메시지 등이다. 위에서 아래로 시간이 흐른다고 보면 된다.","choices":[{"verdict":"오답","why":"생명선(Lifeline)은 객체가 살아 있는 기간을 객체 아래로 뻗은 점선으로 나타내는 시퀀스 다이어그램 구성 요소다."},{"verdict":"오답","why":"실행(Execution, 활성 상자)은 생명선 위의 직사각형으로, 객체가 메시지를 받아 동작을 수행 중인 구간을 나타낸다."},{"verdict":"정답","why":"확장(Extend)은 유스케이스 다이어그램에서 유스케이스 사이의 관계를 나타내는 말로, 시퀀스 다이어그램의 구성 요소가 아니다."},{"verdict":"오답","why":"메시지(Message)는 객체 간에 주고받는 호출·응답을 화살표로 나타내는 시퀀스 다이어그램 구성 요소다."}],"keywords":[{"term":"시퀀스 다이어그램","desc":"객체 간 메시지 교환을 시간 순서로 표현하는 행위 다이어그램"},{"term":"생명선","desc":"객체가 존재하는 기간을 나타내는 세로 점선"},{"term":"확장(extend)","desc":"유스케이스 다이어그램에서 조건에 따라 추가로 수행되는 기능과의 관계"}],"memo":"포함(include)과 확장(extend)은 유스케이스 다이어그램의 관계라고 따로 묶어 둔다."}},{"id":"written-2020-3-7","no":7,"unit":"소프트웨어 설계","q":"객체지향에서 정보 은닉과 가장 밀접한 관계가 있는 것은?","choices":["Encapsulation","Class","Method","Instance"],"ans":1,"rate":82,"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"exp":{"concept":"정보 은닉은 객체 내부의 데이터와 구현을 밖에서 직접 보거나 바꾸지 못하게 숨기는 것이다. 캡슐화(Encapsulation)는 데이터와 그 데이터를 다루는 함수를 하나로 묶는 것으로, 묶은 내부를 감추는 정보 은닉과 가장 밀접하다. 약 캡슐 안의 가루를 직접 만지지 않고 캡슐째 삼키는 것에 비유할 수 있다.","choices":[{"verdict":"정답","why":"캡슐화는 데이터와 메서드를 하나로 묶고 내부 구현을 외부에 감추므로 정보 은닉과 가장 밀접하다."},{"verdict":"오답","why":"클래스(Class)는 공통 속성과 동작을 가진 객체를 만들기 위한 틀(설계도)이다."},{"verdict":"오답","why":"메서드(Method)는 객체가 수행하는 동작, 즉 클래스 안에 정의된 함수다."},{"verdict":"오답","why":"인스턴스(Instance)는 클래스를 바탕으로 실제로 생성된 객체다."}],"keywords":[{"term":"캡슐화","desc":"데이터와 메서드를 묶고 내부를 감추어 외부 영향을 줄이는 객체지향 특징"},{"term":"정보 은닉","desc":"다른 객체에 필요한 인터페이스만 공개하고 내부 정보는 숨기는 것"},{"term":"객체지향 특징","desc":"캡슐화, 상속, 다형성, 추상화, 정보 은닉"}],"memo":"캡슐에 넣어 감춘다 → 캡슐화와 정보 은닉은 한 쌍으로 외운다."}},{"id":"written-2020-3-8","no":8,"unit":"소프트웨어 설계","q":"디자인 패턴 중에서 행위적 패턴에 속하지 않는 것은?","choices":["커맨드 (Command) 패턴","옵저버 (Observer) 패턴","프로토타입 (Prototype) 패턴","상태 (State) 패턴"],"ans":3,"rate":59,"wiki":[{"title":"GoF 디자인 패턴","url":"https://itwiki.kr/w/GoF 디자인 패턴"},{"title":"소프트웨어 디자인 패턴","url":"https://itwiki.kr/w/소프트웨어 디자인 패턴"},{"title":"커맨드 패턴","url":"https://itwiki.kr/w/커맨드 패턴"}],"exp":{"concept":"GoF 디자인 패턴은 목적에 따라 생성, 구조, 행위 패턴으로 나뉜다. 생성 패턴은 객체를 만드는 방법, 구조 패턴은 클래스와 객체를 조합하는 방법, 행위 패턴은 객체 사이의 책임 분배와 상호작용 방법을 다룬다. 프로토타입은 기존 객체를 복제해 새 객체를 만드는 생성 패턴이다.","choices":[{"verdict":"오답","why":"커맨드(Command) 패턴은 요청을 객체로 캡슐화해 실행·취소 등을 다룰 수 있게 하는 행위 패턴이다."},{"verdict":"오답","why":"옵서버(Observer) 패턴은 상태 변화를 의존 객체들에 자동으로 알리는 행위 패턴이다."},{"verdict":"정답","why":"프로토타입(Prototype) 패턴은 원본 객체를 복제해 새 객체를 생성하는 생성 패턴이므로 행위 패턴이 아니다."},{"verdict":"오답","why":"상태(State) 패턴은 객체의 상태에 따라 동작을 바꾸도록 상태를 클래스로 분리하는 행위 패턴이다."}],"keywords":[{"term":"생성 패턴","desc":"Abstract Factory, Builder, Factory Method, Prototype, Singleton"},{"term":"구조 패턴","desc":"Adapter, Bridge, Composite, Decorator, Facade, Flyweight, Proxy"},{"term":"행위 패턴","desc":"Chain of Responsibility, Command, Interpreter, Iterator, Mediator, Memento, Observer, State, Strategy, Template Method, Visitor"}],"memo":"생성 패턴 5개(Abstract Factory, Builder, Factory Method, Prototype, Singleton)를 먼저 외워 두면 나머지 구분이 쉽다."}},{"id":"written-2020-3-9","no":9,"unit":"소프트웨어 설계","q":"UI 설계 원칙 중 누구나 쉽게 이해하고 사용할 수 있어야 한다는 원칙은?","choices":["희소성","유연성","직관성","멀티운용성"],"ans":3,"rate":91,"exp":{"concept":"UI(사용자 인터페이스) 설계 원칙은 직관성, 유효성, 학습성, 유연성 네 가지다. 직관성은 누구나 쉽게 이해하고 사용할 수 있어야 한다는 원칙으로, 설명서 없이도 버튼 모양만 보고 기능을 알 수 있는 상태를 말한다.","choices":[{"verdict":"오답","why":"희소성은 UI 설계 원칙에 포함되지 않는 말이다."},{"verdict":"오답","why":"유연성은 사용자의 요구를 최대한 수용하고 실수를 최소화해야 한다는 원칙으로, 쉽게 이해하는 것과는 다르다."},{"verdict":"정답","why":"누구나 쉽게 이해하고 사용할 수 있어야 한다는 원칙이 직관성이다."},{"verdict":"오답","why":"멀티운용성은 UI 설계 원칙에 포함되지 않는 말이다."}],"keywords":[{"term":"직관성","desc":"누구나 쉽게 이해하고 사용할 수 있어야 함"},{"term":"유효성","desc":"사용자의 목적을 정확하고 완벽하게 달성해야 함"},{"term":"학습성","desc":"누구나 쉽게 배우고 익힐 수 있어야 함"},{"term":"유연성","desc":"사용자 요구를 최대한 수용하고 실수를 최소화해야 함"}],"memo":"UI 설계 원칙은 '직유학유'(직관성·유효성·학습성·유연성)로 외운다."}},{"id":"written-2020-3-10","no":10,"unit":"소프트웨어 설계","q":"코드의 기본 기능으로 거리가 먼 것은?","choices":["복잡성","표준화","분류","식별"],"ans":1,"rate":89,"exp":{"concept":"코드(Code)는 자료를 다루기 쉽게 숫자나 문자로 간단히 나타낸 기호다. 주민등록번호나 상품 바코드처럼, 코드는 대상을 구별하고(식별), 같은 무리로 묶고(분류), 순서대로 늘어놓는(배열) 기능을 하며 표준화·간소화 기능도 있다. 코드는 일을 단순하게 만들려고 쓰는 것이므로 복잡성은 기능이 될 수 없다.","choices":[{"verdict":"정답","why":"코드는 자료 처리를 간단하게 하려는 것이므로 복잡성은 코드의 기능과 거리가 멀다."},{"verdict":"오답","why":"다양한 표현을 하나의 정해진 형식으로 통일하는 표준화는 코드의 기능에 포함된다."},{"verdict":"오답","why":"같은 특성을 가진 자료를 묶는 분류는 코드의 기본 기능이다."},{"verdict":"오답","why":"다른 자료와 구별해 하나를 찾아내는 식별은 코드의 가장 기본적인 기능이다."}],"keywords":[{"term":"코드의 기본 기능","desc":"식별, 분류, 배열 (그 밖에 표준화, 간소화)"},{"term":"코드 종류 예","desc":"순차 코드, 블록 코드, 그룹 분류 코드, 십진 코드, 표의 숫자 코드, 연상 코드 등"}],"memo":"코드는 '식분배'(식별·분류·배열)가 기본이고, 복잡하게 만드는 기능은 없다."}},{"id":"written-2020-3-11","no":11,"unit":"소프트웨어 설계","q":"다음 ( ) 안에 들어갈 내용으로 옳은 것은?\n<img src=\"data/img/eip_written_20200822_011.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["협약(Contract)","프로토콜(Protocol)","패턴(Pattern)","관계(Relation)"],"ans":1,"rate":64,"exp":{"concept":"계약에 의한 설계(Design by Contract)는 컴포넌트를 쓰는 쪽과 제공하는 쪽이 지켜야 할 조건을 계약처럼 명세하는 설계 방법이다. 명세에는 사용 전에 참이어야 할 선행조건, 사용 후 만족해야 할 결과조건, 실행 중 항상 만족해야 할 불변조건이 들어간다.","choices":[{"verdict":"정답","why":"선행조건·결과조건·불변조건을 명세하는 설계 방식은 협약(계약, Contract)에 의한 설계다."},{"verdict":"오답","why":"프로토콜(Protocol)은 통신을 위해 정한 규약으로, 컴포넌트의 선행·결과·불변 조건을 명세하는 설계 방법의 이름이 아니다."},{"verdict":"오답","why":"패턴(Pattern)은 자주 반복되는 설계 문제의 해결 방법을 정리한 것으로, 이 조건 명세 방식과 다르다."},{"verdict":"오답","why":"관계(Relation)는 사물 간의 연관을 뜻하는 일반 용어로, 이런 설계 방법의 이름이 아니다."}],"keywords":[{"term":"계약에 의한 설계","desc":"Design by Contract, 선행조건·결과조건·불변조건을 명세하는 컴포넌트 설계"},{"term":"선행조건","desc":"Precondition, 오퍼레이션 사용 전에 참이어야 할 조건"},{"term":"결과조건","desc":"Postcondition, 오퍼레이션 사용 후 만족되어야 할 조건"},{"term":"불변조건","desc":"Invariant, 오퍼레이션 실행 동안 항상 만족되어야 할 조건"}],"memo":"계약서에는 '전·후·항상' 조건이 있다: 선행·결과·불변."}},{"id":"written-2020-3-12","no":12,"unit":"소프트웨어 설계","q":"UML에서 활용되는 다이어그램 중, 시스템의 동작을 표현하는 행위(Behavioral) 다이어그램에 해당하지 않는 것은?","choices":["유스케이스 다이어그램(Use Case Diagram)","시퀀스 다이어그램(Sequence Diagram)","활동 다이어그램(Activity Diagram)","배치 다이어그램(Deployment Diagram)"],"ans":4,"rate":65,"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"}],"exp":{"concept":"UML 다이어그램은 시스템의 정적인 구조를 그리는 구조(Structural) 다이어그램과 동작을 그리는 행위(Behavioral) 다이어그램으로 나뉜다. 배치 다이어그램은 소프트웨어가 어떤 하드웨어(노드)에 놓이는지를 그리는 구조 다이어그램이다.","choices":[{"verdict":"오답","why":"유스케이스 다이어그램은 사용자 관점에서 시스템이 제공하는 기능을 표현하는 행위 다이어그램이다."},{"verdict":"오답","why":"시퀀스 다이어그램은 객체 간 메시지 교환을 시간 순서로 표현하는 행위 다이어그램이다."},{"verdict":"오답","why":"활동 다이어그램은 처리 흐름을 순서대로 표현하는 행위 다이어그램이다."},{"verdict":"정답","why":"배치 다이어그램(Deployment Diagram)은 결과물·프로세스·컴포넌트가 물리적 노드에 배치되는 모습을 그리는 구조 다이어그램이다."}],"keywords":[{"term":"구조 다이어그램","desc":"클래스, 객체, 컴포넌트, 배치, 복합체 구조, 패키지"},{"term":"행위 다이어그램","desc":"유스케이스, 시퀀스, 커뮤니케이션, 상태, 활동, 상호작용 개요, 타이밍"}],"memo":"물리적으로 '어디에 놓였나'를 그리는 배치·컴포넌트 다이어그램은 구조 쪽이다."}},{"id":"written-2020-3-13","no":13,"unit":"소프트웨어 설계","q":"객체 지향 소프트웨어 공학에서 하나 이상의 유사한 객체들을 묶어서 하나의 공통된 특성을 표현한 것은?","choices":["트랜지션","클래스","시퀀스","서브루틴"],"ans":2,"rate":89,"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"exp":{"concept":"클래스(Class)는 비슷한 객체들이 공통으로 가진 속성과 동작을 묶어 정의한 틀이다. 붕어빵 틀이 클래스라면 그 틀로 찍어 낸 붕어빵 하나하나가 객체(인스턴스)다.","choices":[{"verdict":"오답","why":"트랜지션(Transition)은 상태 다이어그램에서 한 상태에서 다른 상태로 바뀌는 전이를 뜻한다."},{"verdict":"정답","why":"유사한 객체들을 묶어 공통 특성(속성과 연산)을 표현한 것이 클래스다."},{"verdict":"오답","why":"시퀀스(Sequence)는 순서 또는 순차 처리를 뜻하며, 객체를 묶은 단위가 아니다."},{"verdict":"오답","why":"서브루틴(Subroutine)은 프로그램 안에서 반복 사용되는 작은 처리 단위(함수·프로시저)다."}],"keywords":[{"term":"클래스","desc":"공통 속성과 연산을 가진 객체들의 집합을 정의한 틀"},{"term":"인스턴스","desc":"클래스로부터 실제 생성된 객체"}],"memo":"공통 특성을 묶은 틀 = 클래스, 틀로 만든 실체 = 인스턴스."}},{"id":"written-2020-3-14","no":14,"unit":"소프트웨어 설계","q":"아래의 UML 모델에서 '차' 클래스와 각 클래스의 관계로 옳은 것은?\n<img src=\"data/img/eip_written_20200822_014.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["추상화 관계","의존 관계","일반화 관계","그룹 관계"],"ans":3,"rate":59,"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"}],"exp":{"concept":"그림에서 버스·트럭·택시가 속이 빈 삼각형 화살표로 '차'를 가리키고 있다. 이 표기는 일반화(Generalization) 관계로, 하위 클래스가 상위 클래스를 상속하는 'is-a' 관계를 뜻한다. 즉 버스도 차, 트럭도 차, 택시도 차라는 의미다.","choices":[{"verdict":"오답","why":"추상화 관계는 UML 관계의 이름이 아니다. UML 관계는 연관, 집합, 포함, 일반화, 의존, 실체화다."},{"verdict":"오답","why":"의존(Dependency) 관계는 한 클래스가 다른 클래스를 잠시 사용하는 관계로, 점선 화살표로 표시한다."},{"verdict":"정답","why":"속이 빈 삼각형 실선 화살표가 하위 클래스에서 상위 클래스 '차'로 향하므로 일반화(상속) 관계다."},{"verdict":"오답","why":"그룹 관계는 UML 관계의 이름이 아니다."}],"keywords":[{"term":"일반화 관계","desc":"is-a 상속 관계, 실선과 속 빈 삼각형 화살표로 상위 클래스를 가리킴"},{"term":"의존 관계","desc":"짧은 시간 다른 클래스를 사용하는 관계, 점선 화살표"},{"term":"실체화 관계","desc":"인터페이스를 구현하는 관계, 점선과 속 빈 삼각형"}],"memo":"속 빈 삼각형이 실선이면 일반화, 점선이면 실체화다."}},{"id":"written-2020-3-15","no":15,"unit":"소프트웨어 설계","q":"객체지향 소프트웨어 설계시 디자인 패턴을 구성하는 요소로서 가장 거리가 먼 것은?","choices":["개발자이름","문제 및 배경","사례","샘플코드"],"ans":1,"rate":89,"exp":{"concept":"디자인 패턴은 자주 생기는 설계 문제와 해결 방법을 정리해 이름을 붙인 것이다. 문서로 정리할 때는 패턴 이름, 문제 및 배경, 솔루션(해법), 사례, 결과, 샘플 코드 같은 요소를 담는다. 누가 만들었는지는 패턴을 이해하고 적용하는 데 필요한 요소가 아니다.","choices":[{"verdict":"정답","why":"개발자 이름은 패턴을 적용하는 데 필요한 정보가 아니므로 디자인 패턴 구성 요소가 아니다."},{"verdict":"오답","why":"패턴을 어떤 상황에서 쓰는지 설명하는 문제 및 배경은 디자인 패턴의 구성 요소다."},{"verdict":"오답","why":"실제 적용된 사례는 패턴 이해를 돕는 구성 요소에 포함된다."},{"verdict":"오답","why":"패턴을 코드로 보여 주는 샘플 코드는 디자인 패턴의 구성 요소다."}],"keywords":[{"term":"디자인 패턴 구성 요소","desc":"패턴 이름, 문제 및 배경, 솔루션, 사례, 결과, 샘플 코드"},{"term":"GoF","desc":"Gang of Four, 23가지 디자인 패턴을 정리한 네 명의 저자"}],"memo":"패턴 문서에는 '무엇을·왜·어떻게'가 들어가고 '누가'는 들어가지 않는다."}},{"id":"written-2020-3-16","no":16,"unit":"소프트웨어 설계","q":"자료 사전에서 자료의 반복을 의미하는 것은?","choices":["=","( )","{ }","[ ]"],"ans":3,"rate":73,"wiki":[{"title":"자료 사전","url":"https://itwiki.kr/w/자료 사전"}],"exp":{"concept":"자료 사전(Data Dictionary)은 자료 흐름도에 나오는 자료를 기호로 정의해 둔 사전이다. =는 정의, +는 연결, ( )는 생략 가능, [ ]는 여러 개 중 하나 선택, { }는 반복, * *는 주석을 뜻한다.","choices":[{"verdict":"오답","why":"=는 자료를 정의할 때 쓰는 기호로 '~로 구성된다'는 뜻이다."},{"verdict":"오답","why":"( )는 생략할 수 있는 자료(선택 사항)를 표시한다."},{"verdict":"정답","why":"{ }는 자료의 반복을 나타내는 기호다."},{"verdict":"오답","why":"[ ]는 나열된 여러 자료 중 하나를 선택함을 나타낸다. 항목은 |로 구분한다."}],"keywords":[{"term":"자료 사전 기호","desc":"= 정의, + 연결, ( ) 생략, [ ] 선택, { } 반복, * * 주석"},{"term":"자료 사전(DD)","desc":"자료 흐름도의 자료를 정의·기록한 사전, 메타데이터의 일종"}],"memo":"중괄호 { }는 빙글빙글 도는 모양 → 반복, 대괄호 [ ]는 고르기 → 선택."}},{"id":"written-2020-3-17","no":17,"unit":"소프트웨어 설계","q":"객체지향 설계 원칙 중, 서브타입(상속받은 하위 클래스)은 어디에서나 자신의 기반타입(상위클래스)으로 교체할 수 있어야 함을 의미하는 원칙은?","choices":["ISP(Interface Segregation Principle)","DIP(Dependency Inversion Principle)","LSP(Liskov Substitution Principle)","SRP(Single Responsibility Principle)"],"ans":3,"rate":59,"exp":{"concept":"객체지향 설계 원칙(SOLID) 중 리스코프 치환 원칙(LSP)은 자식 클래스가 부모 클래스 자리에 들어가도 프로그램이 문제없이 동작해야 한다는 원칙이다. 예를 들어 '새' 자리에 '참새'를 넣어도 새로서의 동작이 그대로 지켜져야 한다.","choices":[{"verdict":"오답","why":"ISP(인터페이스 분리 원칙)는 클라이언트가 사용하지 않는 메서드에 의존하지 않도록 인터페이스를 작게 나눠야 한다는 원칙이다."},{"verdict":"오답","why":"DIP(의존 역전 원칙)는 구체적인 클래스가 아니라 추상화(인터페이스)에 의존해야 한다는 원칙이다."},{"verdict":"정답","why":"서브타입은 언제나 기반 타입으로 교체할 수 있어야 한다는 것이 LSP(Liskov Substitution Principle)다."},{"verdict":"오답","why":"SRP(단일 책임 원칙)는 하나의 클래스는 하나의 책임만 가져야 한다는 원칙이다."}],"keywords":[{"term":"SOLID","desc":"SRP, OCP, LSP, ISP, DIP 다섯 가지 객체지향 설계 원칙"},{"term":"LSP","desc":"리스코프 치환 원칙, 자식은 부모를 대체할 수 있어야 함"},{"term":"OCP","desc":"개방-폐쇄 원칙, 확장에는 열려 있고 변경에는 닫혀 있어야 함"}],"memo":"치환(Substitution)이라는 단어가 보이면 LSP다."}},{"id":"written-2020-3-18","no":18,"unit":"소프트웨어 설계","q":"자료흐름도(Data Flow Diagram)의 구성요소로 옳은 것은?","choices":["process, data flow, data store, comment","process, data flow, data store, terminator","data flow, data store, terminator, data dictionary","process, data store, terminator, mini-spec"],"ans":2,"rate":78,"wiki":[{"title":"자료 흐름도","url":"https://itwiki.kr/w/자료 흐름도"}],"exp":{"concept":"자료 흐름도(DFD)는 데이터가 시스템 안에서 어떻게 흘러가며 처리되는지 그림으로 나타낸 도구다. 구성 요소는 처리(Process, 원), 자료 흐름(Data Flow, 화살표), 자료 저장소(Data Store, 평행선), 단말(Terminator, 사각형) 네 가지다.","choices":[{"verdict":"오답","why":"comment(주석)는 DFD의 구성 요소가 아니다."},{"verdict":"정답","why":"DFD의 네 구성 요소인 처리, 자료 흐름, 자료 저장소, 단말을 정확히 나열했다."},{"verdict":"오답","why":"data dictionary(자료 사전)는 DFD를 보조하는 별도의 구조적 분석 도구이며, process가 빠져 있다."},{"verdict":"오답","why":"mini-spec(소단위 명세서)은 처리 내용을 기술하는 별도 도구이며, data flow가 빠져 있다."}],"keywords":[{"term":"DFD 구성 요소","desc":"처리(원), 자료 흐름(화살표), 자료 저장소(평행선), 단말(사각형)"},{"term":"구조적 분석 도구","desc":"DFD, 자료 사전(DD), 소단위 명세서(Mini-Spec), 개체 관계도(ERD), 상태 전이도"}],"memo":"DFD 그림에는 원·화살표·평행선·사각형만 있다. 자료 사전과 소단위 명세서는 그림 밖의 별도 문서다."}},{"id":"written-2020-3-19","no":19,"unit":"소프트웨어 설계","q":"CASE(Computer-Aided Software Engineering)도구에 대한 설명으로 거리가 먼 것은?","choices":["소프트웨어 개발 과정의 일부 또는 전체를 자동화하기 위한 도구이다.","표준화된 개발 환경 구축 및 문서 자동화 기능을 제공한다.","작업 과정 및 데이터 공유를 통해 작업자간 커뮤니케이션을 증대한다.","2000년대 이후 소개되었으며, 객체지향 시스템에 한해 효과적으로 활용된다."],"ans":4,"rate":69,"wiki":[{"title":"CASE","url":"https://itwiki.kr/w/CASE"}],"exp":{"concept":"CASE(Computer-Aided Software Engineering)는 소프트웨어 개발 과정의 일부나 전체를 컴퓨터로 자동화해 주는 도구다. 1980년대에 소개되었고, 구조적 기법과 객체지향 기법 등 다양한 개발 방법론에 활용된다.","choices":[{"verdict":"오답","why":"개발 과정의 일부 또는 전체를 자동화하는 것이 CASE의 정의 그대로다."},{"verdict":"오답","why":"CASE는 표준화된 개발 환경을 만들고 문서를 자동으로 작성해 주는 기능을 제공한다."},{"verdict":"오답","why":"작업 과정과 데이터를 공유하므로 작업자 간 의사소통이 늘어난다."},{"verdict":"정답","why":"CASE는 1980년대에 소개되었고, 객체지향뿐 아니라 구조적 기법 등에도 활용되므로 틀린 설명이다."}],"keywords":[{"term":"CASE","desc":"소프트웨어 개발을 자동화하는 도구, 1980년대 소개"},{"term":"상위 CASE","desc":"요구 분석·설계 단계를 지원"},{"term":"하위 CASE","desc":"코드 생성·테스트 등 구현 단계를 지원"}],"memo":"'~에 한해', '~만' 같은 한정하는 표현이 들어간 보기는 틀린 경우가 많다."}},{"id":"written-2020-3-20","no":20,"unit":"소프트웨어 설계","q":"인터페이스 요구 사항 검토 방법에 대한 설명이 옳은 것은?","choices":["리팩토링 : 작성자 이외의 전문 검토 그룹이 요구사항 명세서를 상세히 조사하여 결함, 표준 위배, 문제점 등을 파악","동료검토 : 요구 사항 명세서 작성자가 요구 사항 명세서를 설명하고 이해관계자들이 설명을 들으면서 결함을 발견","인스펙션 : 자동화된 요구 사항 관리 도구를 이용하여 요구 사항 추적성과 일관성을 검토","CASE 도구 : 검토 자료를 회의 전에 배포해서 사전 검토한 후 짧은 시간 동안 검토 회의를 진행하면서 결함을 발견"],"ans":2,"rate":61,"wiki":[{"title":"확인과 검증","url":"https://itwiki.kr/w/확인과 검증"}],"exp":{"concept":"요구사항 검토 방법에는 동료 검토, 워크스루, 인스펙션, 그리고 CASE 도구를 이용한 검토가 있다. 동료 검토는 작성자가 설명하고 동료가 들으며 결함을 찾고, 워크스루는 자료를 미리 배포해 읽어 온 뒤 짧은 회의로 결함을 찾으며, 인스펙션은 작성자가 아닌 전문가 그룹이 상세히 조사한다.","choices":[{"verdict":"오답","why":"작성자 이외의 전문 검토 그룹이 상세히 조사하는 것은 인스펙션이다. 리팩토링은 동작은 그대로 두고 코드 구조를 개선하는 작업이다."},{"verdict":"정답","why":"작성자가 명세서를 설명하고 이해관계자가 들으면서 결함을 찾는 것이 동료 검토(Peer Review)의 정의와 일치한다."},{"verdict":"오답","why":"자동화된 요구사항 관리 도구로 추적성과 일관성을 검토하는 것은 CASE 도구를 이용한 검토다."},{"verdict":"오답","why":"검토 자료를 회의 전에 배포해 사전 검토하고 짧은 회의로 결함을 찾는 것은 워크스루(Walkthrough)다."}],"keywords":[{"term":"동료 검토","desc":"작성자가 설명하고 이해관계자가 들으며 결함 발견"},{"term":"워크스루","desc":"자료를 사전 배포·검토 후 짧은 회의로 결함 발견"},{"term":"인스펙션","desc":"작성자 외 전문 검토 그룹이 상세히 조사해 결함·표준 위배 발견"}],"memo":"설명자가 작성자 본인이면 동료 검토, 사전 배포면 워크스루, 전문 그룹이면 인스펙션."}},{"id":"written-2020-3-21","no":21,"unit":"소프트웨어 개발","q":"인터페이스 보안을 위해 네트워크 영역에 적용될 수 있는 솔루션과 거리가 먼 것은?","choices":["IPSec","SSL","SMTP","S-HTTP"],"ans":3,"rate":74,"wiki":[{"title":"IPSec","url":"https://itwiki.kr/w/IPSec"},{"title":"SSL","url":"https://itwiki.kr/w/SSL"},{"title":"이메일 프로토콜","url":"https://itwiki.kr/w/이메일 프로토콜"}],"exp":{"concept":"인터페이스 보안 중 네트워크 영역에서는 주고받는 데이터를 암호화해 도청이나 변조를 막는다. 대표 기술은 IP 계층의 IPSec, 전송 계층 위의 SSL(TLS), 웹 통신을 암호화하는 S-HTTP다. SMTP는 메일을 보내는 프로토콜일 뿐 보안 솔루션이 아니다.","choices":[{"verdict":"오답","why":"IPSec(IP Security)은 네트워크 계층에서 IP 패킷을 암호화·인증하는 보안 프로토콜이다."},{"verdict":"오답","why":"SSL(Secure Sockets Layer)은 전송 계층 위에서 데이터를 암호화하는 보안 프로토콜로, 현재는 TLS로 발전했다."},{"verdict":"정답","why":"SMTP(Simple Mail Transfer Protocol)는 전자우편 전송 프로토콜로, 네트워크 보안 솔루션이 아니다."},{"verdict":"오답","why":"S-HTTP(Secure HTTP)는 웹에서 클라이언트와 서버 간 메시지를 암호화하는 보안 프로토콜이다."}],"keywords":[{"term":"IPSec","desc":"네트워크 계층에서 IP 패킷을 암호화·인증하는 프로토콜"},{"term":"SSL/TLS","desc":"전송 계층 위에서 통신을 암호화하는 프로토콜"},{"term":"S-HTTP","desc":"HTTP 메시지를 암호화하는 웹 보안 프로토콜"}],"memo":"이름에 S(Secure)가 붙거나 Sec가 들어가면 보안 프로토콜, SMTP의 S는 Simple이다."}},{"id":"written-2020-3-22","no":22,"unit":"소프트웨어 개발","q":"소프트웨어 공학의 기본 원칙이라고 볼 수 없는 것은?","choices":["품질 높은 소프트웨어 상품 개발","지속적인 검증 시행","결과에 대한 명확한 기록 유지","최대한 많은 인력 투입"],"ans":4,"rate":96,"wiki":[{"title":"소프트웨어 공학","url":"https://itwiki.kr/w/소프트웨어 공학"}],"exp":{"concept":"소프트웨어 공학은 좋은 품질의 소프트웨어를 경제적으로 만들기 위한 학문이다. 기본 원칙은 현대적인 프로그래밍 기술을 계속 적용하고, 개발 과정에서 지속적으로 검증하며, 결과를 명확히 기록으로 남기는 것이다. 사람을 많이 넣는다고 품질이 좋아지지는 않는다.","choices":[{"verdict":"오답","why":"품질 높은 소프트웨어를 만드는 것은 소프트웨어 공학의 목표이자 기본 원칙에 해당한다."},{"verdict":"오답","why":"개발 단계마다 지속적으로 검증하는 것은 소프트웨어 공학의 기본 원칙이다."},{"verdict":"오답","why":"결과에 대한 명확한 기록 유지는 소프트웨어 공학의 기본 원칙이다."},{"verdict":"정답","why":"인력을 최대한 많이 투입하는 것은 원칙이 아니며, 오히려 의사소통 비용이 늘어 효율이 떨어질 수 있다."}],"keywords":[{"term":"소프트웨어 공학 기본 원칙","desc":"현대적 프로그래밍 기술 적용, 지속적 검증, 결과의 명확한 기록 유지"},{"term":"브룩스의 법칙","desc":"지연되는 프로젝트에 인력을 더 투입하면 오히려 더 늦어진다는 법칙"}],"memo":"브룩스의 법칙을 떠올리면 '인력 최대 투입'은 원칙이 될 수 없다는 것을 바로 알 수 있다."}},{"id":"written-2020-3-23","no":23,"unit":"소프트웨어 개발","q":"패키지 소프트웨어의 일반적인 제품 품질 요구사항 및 테스트를 위한 국제 표준은?","choices":["ISO/IEC 2196","IEEE 19554","ISO/IEC 12119","ISO/IEC 14959"],"ans":3,"rate":68,"exp":{"concept":"ISO/IEC 12119는 패키지 소프트웨어의 품질 요구사항과 테스트에 관한 국제 표준이다. 제품 설명서, 사용자 문서, 프로그램과 데이터가 갖춰야 할 품질 요구와 이를 시험하는 방법을 규정한다.","choices":[{"verdict":"오답","why":"ISO/IEC 2196은 패키지 소프트웨어 품질 표준이 아니며 출제 범위의 표준 번호가 아니다."},{"verdict":"오답","why":"IEEE 19554는 패키지 소프트웨어 품질 표준이 아니며 출제 범위의 표준 번호가 아니다."},{"verdict":"정답","why":"패키지 소프트웨어의 일반적인 제품 품질 요구사항 및 테스트를 위한 국제 표준은 ISO/IEC 12119다."},{"verdict":"오답","why":"ISO/IEC 14959는 패키지 소프트웨어 품질 표준이 아니며 출제 범위의 표준 번호가 아니다."}],"keywords":[{"term":"ISO/IEC 12119","desc":"패키지 소프트웨어 품질 요구사항 및 테스트 표준"},{"term":"ISO/IEC 9126","desc":"소프트웨어 제품 품질 특성(기능성, 신뢰성, 사용성, 효율성, 유지보수성, 이식성)"},{"term":"ISO/IEC 25000","desc":"SQuaRE, 9126 등을 통합한 소프트웨어 품질 평가 표준"}],"memo":"패키지 소프트웨어 품질·테스트 = 12119, 제품 품질 특성 = 9126, 이 둘을 짝지어 외운다."}},{"id":"written-2020-3-24","no":24,"unit":"소프트웨어 개발","q":"다음 중 클린 코드 작성원칙으로 거리가 먼 것은?","choices":["누구든지 쉽게 이해하는 코드 작성","중복이 최대화된 코드 작성","다른 모듈에 미치는 영향 최소화","단순, 명료한 코드 작성"],"ans":2,"rate":94,"wiki":[{"title":"클린 코드","url":"https://itwiki.kr/w/클린 코드"}],"exp":{"concept":"클린 코드는 누가 읽어도 이해하기 쉽고 고치기 쉬운 깔끔한 코드다. 작성 원칙은 가독성, 단순성, 의존성 배제(다른 모듈에 미치는 영향 최소화), 중복성 최소화, 추상화다. 같은 코드가 여러 곳에 있으면 고칠 때 빠뜨리기 쉬우므로 중복은 줄여야 한다.","choices":[{"verdict":"오답","why":"누구든지 쉽게 이해하는 코드는 가독성 원칙에 해당한다."},{"verdict":"정답","why":"클린 코드는 중복을 최소화해야 하므로 중복을 최대화한다는 것은 원칙과 반대다."},{"verdict":"오답","why":"다른 모듈에 미치는 영향을 최소화하는 것은 의존성 배제 원칙이다."},{"verdict":"오답","why":"단순하고 명료한 코드는 단순성 원칙에 해당한다."}],"keywords":[{"term":"클린 코드 원칙","desc":"가독성, 단순성, 의존성 배제, 중복성 최소화, 추상화"},{"term":"DRY","desc":"Don't Repeat Yourself, 같은 코드를 반복하지 말라는 원칙"}],"memo":"클린 코드에서 '최대화'되는 것은 없다. 중복·의존·복잡은 모두 최소화 대상이다."}},{"id":"written-2020-3-25","no":25,"unit":"소프트웨어 개발","q":"블랙박스 테스트의 유형으로 틀린 것은?","choices":["경계값 분석","오류 예측","동등 분할 기법","조건, 루프 검사"],"ans":4,"rate":67,"exp":{"concept":"블랙박스 테스트는 프로그램 내부 구조를 보지 않고 입력과 출력만으로 기능이 맞는지 확인하는 테스트다. 동등 분할, 경계값 분석, 원인-효과 그래프, 오류 예측, 비교 검사가 대표 기법이다. 조건 검사나 루프 검사처럼 코드 내부의 분기와 반복을 직접 보는 기법은 화이트박스 테스트다.","choices":[{"verdict":"오답","why":"경계값 분석은 입력 범위의 경계에서 오류가 많다는 점을 이용하는 블랙박스 기법이다."},{"verdict":"오답","why":"오류 예측은 경험과 감각으로 오류가 날 만한 곳을 예상해 테스트하는 블랙박스 기법이다."},{"verdict":"오답","why":"동등 분할 기법은 입력을 유효·무효 그룹으로 나누어 대표값으로 테스트하는 블랙박스 기법이다."},{"verdict":"정답","why":"조건 검사와 루프 검사는 코드 내부의 조건문과 반복문을 검사하는 화이트박스 테스트 기법이다."}],"keywords":[{"term":"블랙박스 테스트","desc":"동등 분할, 경계값 분석, 원인-효과 그래프, 오류 예측, 비교 검사"},{"term":"화이트박스 테스트","desc":"기초 경로 검사, 조건 검사, 루프 검사, 데이터 흐름 검사"}],"memo":"코드 속 조건·루프·경로를 본다면 화이트박스, 입력값만 고민한다면 블랙박스."}},{"id":"written-2020-3-26","no":26,"unit":"소프트웨어 개발","q":"제어흐름 그래프가 다음과 같을 때 McCabe의 cyclomatic 수는 얼마인가?\n<img src=\"data/img/eip_written_20200822_026.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["3","4","5","6"],"ans":2,"rate":64,"exp":{"concept":"McCabe의 순환 복잡도(Cyclomatic Complexity)는 제어 흐름 그래프에서 독립적인 경로가 몇 개인지를 나타내는 수다. 공식은 V(G) = E - N + 2이며 E는 간선(화살표) 수, N은 노드 수다. 그림의 간선은 a→b, a→c, b→c, c→d, d→c, d→a로 6개, 노드는 a, b, c, d로 4개이므로 V(G) = 6 - 4 + 2 = 4다.","choices":[{"verdict":"오답","why":"c와 d 사이의 곡선 화살표(d→c)를 빠뜨려 간선을 5개로 세면 나오는 값이다."},{"verdict":"정답","why":"간선 6개, 노드 4개이므로 V(G) = 6 - 4 + 2 = 4다. 닫힌 영역 3개에 바깥 영역 1개를 더해도 4가 된다."},{"verdict":"오답","why":"V(G) = 5가 되려면 노드 4개에 간선이 7개여야 하는데, 그림의 간선은 6개다."},{"verdict":"오답","why":"간선 수 6을 그대로 답으로 고른 경우로, 노드 수를 빼고 2를 더해야 한다."}],"keywords":[{"term":"순환 복잡도","desc":"V(G) = E - N + 2, 독립 경로의 수"},{"term":"다른 계산법","desc":"V(G) = 닫힌 영역 수 + 1 = 조건(분기) 노드 수 + 1"}],"memo":"화살표 머리를 하나씩 세어야 서로 반대로 향하는 두 간선(c→d, d→c)을 놓치지 않는다."}},{"id":"written-2020-3-27","no":27,"unit":"소프트웨어 개발","q":"다음 자료에 대하여 선택(Selection) 정렬을 이용하여 오름차순으로 정렬하고자 한다. 3회전 후의 결과로 옳은 것은?\n<img src=\"data/img/eip_written_20200822_027.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["14, 17, 37, 40, 35","14, 37, 17, 40, 35","17, 14, 37, 35, 40","14, 17, 35, 40, 37"],"ans":4,"rate":65,"wiki":[{"title":"선택 정렬","url":"https://itwiki.kr/w/선택 정렬"}],"exp":{"concept":"선택 정렬(Selection Sort)은 매 회전마다 정렬되지 않은 부분에서 가장 작은 값을 찾아 맨 앞자리와 바꾸는 방식이다. 37, 14, 17, 40, 35에서 1회전은 최솟값 14를 첫 자리 37과 바꿔 14, 37, 17, 40, 35가 된다. 2회전은 나머지 중 최솟값 17을 둘째 자리 37과 바꿔 14, 17, 37, 40, 35, 3회전은 나머지 37, 40, 35 중 최솟값 35를 셋째 자리 37과 바꿔 14, 17, 35, 40, 37이 된다.","choices":[{"verdict":"오답","why":"14, 17, 37, 40, 35는 2회전 후의 결과다."},{"verdict":"오답","why":"14, 37, 17, 40, 35는 1회전 후의 결과다."},{"verdict":"오답","why":"선택 정렬은 1회전에 최솟값 14를 맨 앞에 두므로 17로 시작하는 결과는 나올 수 없다."},{"verdict":"정답","why":"3회전에서 남은 37, 40, 35 중 최솟값 35와 셋째 자리 37이 바뀌어 14, 17, 35, 40, 37이 된다."}],"keywords":[{"term":"선택 정렬","desc":"남은 값 중 최솟값을 찾아 앞자리와 교환, 비교 횟수 n(n-1)/2"},{"term":"버블 정렬","desc":"이웃한 두 값을 비교해 교환, 한 회전마다 가장 큰 값이 맨 뒤로 이동"}],"memo":"선택 정렬은 k회전 후 앞에서 k개가 최종 위치에 고정된다. 3회전 후 앞 세 개는 14, 17, 35."}},{"id":"written-2020-3-28","no":28,"unit":"소프트웨어 개발","q":"형상 관리 도구의 주요 기능으로 거리가 먼 것은?","choices":["정규화(Normalization)","체크인(Check-in)","체크아웃(Check-out)","커밋(commit)"],"ans":1,"rate":71,"exp":{"concept":"형상 관리 도구는 소스 코드와 문서의 변경 이력을 관리하는 도구다(예: Git, SVN, CVS). 저장소에서 파일을 가져오는 체크아웃, 수정한 파일을 저장소에 올리는 체크인, 변경 내용을 확정해 반영하는 커밋이 주요 기능이다. 정규화는 데이터베이스 설계 용어다.","choices":[{"verdict":"정답","why":"정규화(Normalization)는 데이터베이스에서 중복과 이상 현상을 줄이려고 릴레이션을 분해하는 작업으로, 형상 관리 기능이 아니다."},{"verdict":"오답","why":"체크인(Check-in)은 수정한 파일을 저장소에 반영하는 형상 관리 기능이다."},{"verdict":"오답","why":"체크아웃(Check-out)은 저장소에서 파일을 받아 오는 형상 관리 기능이다."},{"verdict":"오답","why":"커밋(commit)은 변경 내용을 저장소에 확정해 기록하는 형상 관리 기능이다."}],"keywords":[{"term":"형상 관리 도구 주요 기능","desc":"체크인, 체크아웃, 커밋 (그 밖에 임포트, 업데이트, 머지 등)"},{"term":"형상 관리 도구 예","desc":"CVS, SVN, Git"}],"memo":"정규화는 DB 과목 용어. 과목이 다른 용어를 섞어 놓은 보기가 정답인 경우가 많다."}},{"id":"written-2020-3-29","no":29,"unit":"소프트웨어 개발","q":"다음 트리를 Preorder 운행법으로 운행할 경우 가장 먼저 탐색되는 것은?\n<img src=\"data/img/eip_written_20200822_029.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["A","B","D","G"],"ans":1,"rate":77,"wiki":[{"title":"트리","url":"https://itwiki.kr/w/트리"}],"exp":{"concept":"전위 순회(Preorder)는 루트 → 왼쪽 서브트리 → 오른쪽 서브트리 순서로 방문한다. 그래서 가장 먼저 방문하는 노드는 항상 루트다. 그림의 루트는 A이며, 전체 전위 순회 결과는 A, B, D, C, E, G, H, F다.","choices":[{"verdict":"정답","why":"전위 순회는 루트부터 방문하므로 루트인 A가 가장 먼저 탐색된다."},{"verdict":"오답","why":"B는 루트 A 다음, 두 번째로 방문된다."},{"verdict":"오답","why":"D는 중위 순회(D, B, A, G, E, H, C, F)와 후위 순회(D, B, G, H, E, F, C, A)에서 가장 먼저 방문되는 노드다."},{"verdict":"오답","why":"G는 전위 순회에서 여섯 번째로 방문된다."}],"keywords":[{"term":"전위 순회","desc":"Preorder, Root → Left → Right"},{"term":"중위 순회","desc":"Inorder, Left → Root → Right"},{"term":"후위 순회","desc":"Postorder, Left → Right → Root"}],"memo":"전·중·후는 루트를 언제 방문하느냐로 구분한다. 전위는 처음, 후위는 마지막이 루트."}},{"id":"written-2020-3-30","no":30,"unit":"소프트웨어 개발","q":"소프트웨어 품질 목표 중 주어진 시간동안 주어진 기능을 오류없이 수행하는 정도를 나타내는 것은?","choices":["직관성","사용 용이성","신뢰성","이식성"],"ans":3,"rate":78,"exp":{"concept":"소프트웨어 품질 목표 중 신뢰성(Reliability)은 주어진 시간 동안 주어진 기능을 오류 없이 수행하는 정도다. 자동차가 고장 없이 오래 잘 달리는 것처럼, 믿고 쓸 수 있는 정도를 말한다.","choices":[{"verdict":"오답","why":"직관성은 누구나 쉽게 이해하고 사용할 수 있어야 한다는 UI 설계 원칙이다."},{"verdict":"오답","why":"사용 용이성은 사용자가 쉽게 배우고 사용할 수 있는 정도다."},{"verdict":"정답","why":"주어진 시간 동안 주어진 기능을 오류 없이 수행하는 정도가 신뢰성의 정의다."},{"verdict":"오답","why":"이식성은 다른 환경(하드웨어, 운영체제)에서도 쉽게 수정해 사용할 수 있는 정도다."}],"keywords":[{"term":"신뢰성","desc":"주어진 시간 동안 주어진 기능을 오류 없이 수행하는 정도"},{"term":"이식성","desc":"다른 환경에서도 쉽게 사용할 수 있는 정도"},{"term":"효율성","desc":"최소한의 자원으로 기능을 수행하는 정도"}],"memo":"'오류 없이'가 보이면 신뢰성, '다른 환경에서'가 보이면 이식성."}},{"id":"written-2020-3-31","no":31,"unit":"소프트웨어 개발","q":"알고리즘 설계 기법으로 거리가 먼 것은?","choices":["Divide and Conquer","Greedy","Static Block","Backtracking"],"ans":3,"rate":55,"wiki":[{"title":"알고리즘","url":"https://itwiki.kr/w/알고리즘"}],"exp":{"concept":"알고리즘 설계 기법은 문제를 푸는 전략의 종류다. 분할 정복, 탐욕(Greedy), 동적 계획법, 백트래킹, 분기 한정 등이 있다. Static Block은 자바에서 클래스가 로드될 때 한 번 실행되는 정적 초기화 블록으로, 알고리즘 설계 기법이 아니다.","choices":[{"verdict":"오답","why":"분할 정복(Divide and Conquer)은 문제를 작은 문제로 나누어 풀고 결과를 합치는 설계 기법이다(예: 합병 정렬, 퀵 정렬)."},{"verdict":"오답","why":"탐욕 기법(Greedy)은 매 순간 가장 좋아 보이는 선택을 하는 설계 기법이다."},{"verdict":"정답","why":"Static Block은 프로그래밍 언어의 정적 초기화 블록으로, 알고리즘 설계 기법이 아니다."},{"verdict":"오답","why":"백트래킹(Backtracking)은 해를 찾다가 막히면 되돌아가 다른 경로를 시도하는 설계 기법이다."}],"keywords":[{"term":"알고리즘 설계 기법","desc":"분할 정복, 동적 계획법, 탐욕 기법, 백트래킹, 분기 한정"},{"term":"동적 계획법","desc":"작은 문제의 답을 저장해 두고 재사용해 큰 문제를 푸는 기법"}],"memo":"Static은 코드 문법 용어다. 알고리즘 설계 기법은 '문제를 어떻게 쪼개고 고르느냐'에 관한 이름이다."}},{"id":"written-2020-3-32","no":32,"unit":"소프트웨어 개발","q":"제품 소프트웨어의 형상 관리 역할로 틀린 것은?","choices":["형상 관리를 통해 이전 리버전이나 버전에 대한 정보에 접근 가능하여 배포본 관리에 유용","불필요한 사용자의 소스 수정 제한","프로젝트 개발비용을 효율적으로 관리","동일한 프로젝트에 대해 여러 개발자 동시 개발 가능"],"ans":3,"rate":53,"exp":{"concept":"형상 관리는 소프트웨어의 변경 사항을 체계적으로 추적하고 통제하는 활동이다. 이전 버전을 찾아볼 수 있고, 허가되지 않은 수정을 막으며, 여러 개발자가 동시에 작업할 수 있게 해 준다. 개발 비용을 관리하는 것은 프로젝트 관리의 역할이다.","choices":[{"verdict":"오답","why":"이전 리비전이나 버전 정보에 접근할 수 있어 배포본 관리에 유용한 것은 형상 관리의 역할이다."},{"verdict":"오답","why":"권한 없는 사용자의 소스 수정을 제한하는 것은 형상 관리의 역할이다."},{"verdict":"정답","why":"개발 비용을 효율적으로 관리하는 것은 프로젝트 관리(비용 관리)의 역할이지 형상 관리의 역할이 아니다."},{"verdict":"오답","why":"동일 프로젝트에서 여러 개발자가 동시에 개발할 수 있게 하는 것은 형상 관리의 역할이다."}],"keywords":[{"term":"형상 관리","desc":"SCM, 소프트웨어 변경 사항을 식별·통제·기록·감사하는 활동"},{"term":"형상 관리 절차","desc":"형상 식별, 형상 통제, 형상 감사, 형상 기록"}],"memo":"형상 관리는 '변경'을 관리한다. 비용·일정은 프로젝트 관리 영역이다."}},{"id":"written-2020-3-33","no":33,"unit":"소프트웨어 개발","q":"제품 소프트웨어 패키징 도구 활용 시 고려사항이 아닌 것은?","choices":["제품 소프트웨어의 종류에 적합한 암호화 알고리즘을 고려한다.","추가로 다양한 이기종 연동을 고려한다.","사용자 편의성을 위한 복잡성 및 비효율성 문제를 고려한다.","내부 콘텐츠에 대한 보안은 고려하지 않는다."],"ans":4,"rate":90,"exp":{"concept":"패키징 도구는 소프트웨어를 배포할 때 암호화와 보안을 적용해 불법 복제와 유출을 막는 도구다. 활용할 때는 소프트웨어 종류에 맞는 암호화 알고리즘, 다양한 이기종 콘텐츠와 단말기의 연동, 보안을 위해 생기는 복잡성과 비효율성에 따른 사용자 편의성을 고려해야 한다. 내부 콘텐츠 보안은 반드시 고려해야 한다.","choices":[{"verdict":"오답","why":"제품 소프트웨어 종류에 맞는 암호화 알고리즘을 적용하는 것은 패키징 도구 활용 시 고려사항이다."},{"verdict":"오답","why":"여러 이기종 콘텐츠·단말기와의 연동을 고려하는 것은 고려사항에 포함된다."},{"verdict":"오답","why":"보안을 적용하면 생기는 복잡성과 비효율성 때문에 사용자 편의성을 고려해야 한다는 것은 맞는 고려사항이다."},{"verdict":"정답","why":"패키징 도구는 내부 콘텐츠를 암호화해 보호하는 것이 목적이므로 보안을 고려하지 않는다는 설명은 틀렸다."}],"keywords":[{"term":"패키징 도구","desc":"배포용 소프트웨어에 암호화·보안을 적용해 패키징하는 도구"},{"term":"패키징 도구 고려사항","desc":"반드시 내부 콘텐츠 암호화·보안 고려, 이기종 연동 고려, 사용자 편의성, 적합한 암호화 알고리즘"}],"memo":"보안을 '고려하지 않는다'는 보기는 보안 관련 문항에서 거의 항상 틀린 말이다."}},{"id":"written-2020-3-34","no":34,"unit":"소프트웨어 개발","q":"디지털 저작권 관리(DRM) 기술과 거리가 먼 것은?","choices":["콘텐츠 암호화 및 키 관리","콘텐츠 식별체계 표현","콘텐츠 오류 감지 및 복구","라이센스 발급 및 관리"],"ans":3,"rate":76,"exp":{"concept":"디지털 저작권 관리(DRM, Digital Rights Management)는 디지털 콘텐츠를 허가된 사용자만 허가된 방법으로 쓰도록 보호하는 기술이다. 콘텐츠 암호화와 키 관리, 콘텐츠 식별 체계, 저작권 표현, 라이선스 발급·관리, 정책 관리, 크랙 방지, 인증 등의 기술로 구성된다. 오류 감지·복구는 데이터 전송이나 저장 분야의 기술이다.","choices":[{"verdict":"오답","why":"콘텐츠를 암호화하고 키를 관리하는 것은 DRM의 핵심 기술이다."},{"verdict":"오답","why":"콘텐츠를 구별하기 위한 식별 체계(예: DOI, URI) 표현은 DRM 기술에 포함된다."},{"verdict":"정답","why":"콘텐츠 오류 감지 및 복구는 전송·저장 오류를 다루는 기술로, 저작권 보호를 위한 DRM 기술과 거리가 멀다."},{"verdict":"오답","why":"사용 권한을 담은 라이선스를 발급하고 관리하는 것은 DRM 기술이다."}],"keywords":[{"term":"DRM","desc":"디지털 콘텐츠의 저작권을 보호하고 사용을 통제하는 기술"},{"term":"DRM 구성 요소","desc":"콘텐츠 제공자, 콘텐츠 분배자, 패키저, 보안 컨테이너, DRM 컨트롤러, 클리어링 하우스"},{"term":"클리어링 하우스","desc":"저작권 사용 권한·라이선스 발급과 결제를 관리하는 곳"}],"memo":"DRM은 '권리(Rights)'를 지키는 기술이다. 오류 복구는 권리와 상관없다."}},{"id":"written-2020-3-35","no":35,"unit":"소프트웨어 개발","q":"물리데이터 저장소의 파티션 설계에서 파티션 유형으로 옳지 않은 것은?","choices":["범위분할(Range Partitioning)","해시분할(Hash Partitioning)","조합분할(Composite Partitioning)","유닛분할(Unit Partitioning)"],"ans":4,"rate":53,"exp":{"concept":"파티셔닝은 큰 테이블을 여러 조각(파티션)으로 나누어 저장하는 것이다. 값의 범위로 나누는 범위 분할, 해시 함수로 나누는 해시 분할, 지정한 값 목록으로 나누는 목록 분할, 이들을 섞은 조합 분할이 있다.","choices":[{"verdict":"오답","why":"범위 분할(Range)은 날짜·숫자 같은 열 값의 범위를 기준으로 나누는 파티션 유형이다."},{"verdict":"오답","why":"해시 분할(Hash)은 해시 함수 값에 따라 데이터를 고르게 나누는 파티션 유형이다."},{"verdict":"오답","why":"조합 분할(Composite)은 범위 분할 후 다시 해시 분할하는 식으로 두 가지 이상을 조합한 파티션 유형이다."},{"verdict":"정답","why":"유닛 분할(Unit Partitioning)이라는 파티션 유형은 없다."}],"keywords":[{"term":"파티션 유형","desc":"범위 분할, 해시 분할, 목록 분할, 조합 분할"},{"term":"목록 분할","desc":"List Partitioning, 지정한 값 목록(예: 지역명)을 기준으로 분할"}],"memo":"파티션 유형은 '범해목조'(범위·해시·목록·조합)로 외운다."}},{"id":"written-2020-3-36","no":36,"unit":"소프트웨어 개발","q":"다음이 설명하는 애플리케이션 통합 테스트 유형은?\n<img src=\"data/img/eip_written_20200822_036.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["하향식 통합 테스트","상향식 통합 테스트","회귀 테스트","빅뱅 테스트"],"ans":1,"rate":89,"wiki":[{"title":"통합 테스트","url":"https://itwiki.kr/w/통합 테스트"}],"exp":{"concept":"통합 테스트는 단위 테스트를 마친 모듈을 합치면서 인터페이스 오류를 찾는 테스트다. 하향식 통합은 상위 모듈부터 테스트하며 아래로 내려가고, 아직 없는 하위 모듈은 임시 모듈인 스텁(Stub)으로 대신한다. 통합 순서는 깊이 우선이나 너비 우선 방식을 쓴다.","choices":[{"verdict":"정답","why":"상위 컴포넌트부터 점증적으로 하위로 통합하고, 하위가 없으면 스텁을 쓰며, 깊이·너비 우선 방식이 있는 것은 하향식 통합 테스트다."},{"verdict":"오답","why":"상향식 통합 테스트는 하위 모듈부터 통합하며, 상위 모듈 대신 테스트 드라이버(Driver)를 사용하고 클러스터 단위로 묶는다."},{"verdict":"오답","why":"회귀 테스트는 수정 후 기존 기능에 새 오류가 생기지 않았는지 반복 확인하는 테스트다."},{"verdict":"오답","why":"빅뱅 테스트는 모든 모듈을 한꺼번에 합쳐 테스트하는 비점진적 방식이다."}],"keywords":[{"term":"하향식 통합","desc":"상위 → 하위로 통합, 스텁(Stub) 사용, 깊이·너비 우선"},{"term":"상향식 통합","desc":"하위 → 상위로 통합, 드라이버(Driver) 사용, 클러스터 단위"},{"term":"스텁","desc":"아직 없는 하위 모듈을 대신하는 임시 모듈"}],"memo":"하향식은 스텁, 상향식은 드라이버. '위에서 내려오면 아래가 비어 스텁'으로 기억한다."}},{"id":"written-2020-3-37","no":37,"unit":"소프트웨어 개발","q":"인터페이스 구현시 사용하는 기술 중 다음 내용이 설명하는 것은?\n<img src=\"data/img/eip_written_20200822_037.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Procedure","Trigger","Greedy","AJAX"],"ans":4,"rate":80,"exp":{"concept":"AJAX(Asynchronous JavaScript and XML)는 자바스크립트로 서버와 비동기 통신을 해서, 웹 페이지 전체를 새로 고치지 않고 필요한 데이터(XML 등)만 주고받는 기술이다. 검색창에 글자를 치면 바로 추천어가 뜨는 기능이 대표적인 예다.","choices":[{"verdict":"오답","why":"Procedure(프로시저)는 데이터베이스에 저장해 두고 호출해 실행하는 SQL 문 묶음이다."},{"verdict":"오답","why":"Trigger(트리거)는 데이터 삽입·수정·삭제 같은 이벤트가 발생하면 자동으로 실행되는 프로시저다."},{"verdict":"오답","why":"Greedy(탐욕 기법)는 매 순간 최선으로 보이는 선택을 하는 알고리즘 설계 기법이다."},{"verdict":"정답","why":"자바스크립트를 사용한 비동기 통신으로 클라이언트와 서버가 XML 데이터를 주고받는 기술이 AJAX다."}],"keywords":[{"term":"AJAX","desc":"Asynchronous JavaScript and XML, 비동기 웹 통신 기술"},{"term":"JSON","desc":"속성-값 쌍으로 데이터를 표현하는 경량 데이터 교환 형식"},{"term":"인터페이스 구현 기술","desc":"JSON, XML, AJAX, REST 등"}],"memo":"AJAX의 A는 Asynchronous(비동기), J는 JavaScript, X는 XML."}},{"id":"written-2020-3-38","no":38,"unit":"소프트웨어 개발","q":"소프트웨어 재공학이 소프트웨어의 재개발에 비해 갖는 장점으로 거리가 먼 것은?","choices":["위험부담 감소","비용 절감","시스템 명세의 오류억제","개발시간의 증가"],"ans":4,"rate":91,"wiki":[{"title":"소프트웨어 재공학","url":"https://itwiki.kr/w/소프트웨어 재공학"}],"exp":{"concept":"소프트웨어 재공학은 기존 소프트웨어를 버리지 않고 분석·수정해 더 좋은 시스템으로 바꾸는 것이다. 처음부터 다시 만드는 재개발보다 위험 부담이 적고, 비용이 덜 들고, 개발 시간이 줄며, 이미 검증된 명세를 쓰므로 명세 오류도 줄어든다.","choices":[{"verdict":"오답","why":"이미 동작하는 시스템을 바탕으로 하므로 위험 부담이 줄어드는 것은 재공학의 장점이다."},{"verdict":"오답","why":"기존 자산을 재사용하므로 비용이 절감되는 것은 재공학의 장점이다."},{"verdict":"오답","why":"검증된 기존 시스템의 명세를 활용하므로 명세 오류가 억제되는 것은 재공학의 장점이다."},{"verdict":"정답","why":"재공학은 개발 시간을 줄이는 것이 장점이므로 개발 시간의 증가는 장점이 될 수 없다."}],"keywords":[{"term":"소프트웨어 재공학","desc":"기존 시스템을 분석·재구성해 유지보수성과 품질을 높이는 것"},{"term":"재공학 과정","desc":"분석, 재구성, 역공학, 이관"},{"term":"역공학","desc":"기존 코드에서 거꾸로 설계 정보와 명세를 추출하는 것"}],"memo":"'장점이 아닌 것' 문항에서 '증가', '어려움' 같은 부정적인 단어가 붙은 보기를 먼저 의심한다."}},{"id":"written-2020-3-39","no":39,"unit":"소프트웨어 개발","q":"알파, 베타 테스트와 가장 밀접한 연관이 있는 테스트 단계는?","choices":["단위 테스트","인수 테스트","통합 테스트","시스템 테스트"],"ans":2,"rate":56,"wiki":[{"title":"인수 테스트","url":"https://itwiki.kr/w/인수 테스트"},{"title":"단위 테스트","url":"https://itwiki.kr/w/단위 테스트"},{"title":"통합 테스트","url":"https://itwiki.kr/w/통합 테스트"},{"title":"시스템 테스트","url":"https://itwiki.kr/w/시스템 테스트"}],"exp":{"concept":"인수 테스트는 개발이 끝난 소프트웨어를 사용자가 직접 확인해 받아들일지(인수) 결정하는 마지막 테스트 단계다. 알파 테스트는 개발자 환경에서 사용자가 테스트하고 개발자가 지켜보는 방식, 베타 테스트는 실제 사용자 환경에서 사용자가 직접 테스트하는 방식으로 둘 다 인수 테스트에 속한다.","choices":[{"verdict":"오답","why":"단위 테스트는 모듈 하나하나를 개별적으로 테스트하는 단계로 주로 개발자가 수행한다."},{"verdict":"정답","why":"알파 테스트와 베타 테스트는 사용자가 참여해 인수 여부를 판단하는 인수 테스트의 종류다."},{"verdict":"오답","why":"통합 테스트는 모듈을 결합하면서 인터페이스 오류를 찾는 단계다."},{"verdict":"오답","why":"시스템 테스트는 통합된 시스템 전체가 기능·비기능 요구를 만족하는지 개발 측에서 확인하는 단계다."}],"keywords":[{"term":"알파 테스트","desc":"개발자 장소에서 사용자가 테스트, 개발자가 함께 관찰"},{"term":"베타 테스트","desc":"실제 사용자 환경에서 사용자가 테스트, 개발자는 참여하지 않음"},{"term":"테스트 단계","desc":"단위 → 통합 → 시스템 → 인수 테스트"}],"memo":"알파는 개발자 곁에서, 베타는 사용자 집에서. 둘 다 사용자가 하므로 인수 테스트다."}},{"id":"written-2020-3-40","no":40,"unit":"소프트웨어 개발","q":"다음 트리의 차수(degree)는?\n<img src=\"data/img/eip_written_20200822_040.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["2","3","4","5"],"ans":2,"rate":66,"exp":{"concept":"트리의 차수(degree)는 각 노드가 가진 자식 수 중 가장 큰 값이다. 그림에서 A의 자식은 B, C로 2개, B의 자식은 D, E, F로 3개, C의 자식은 G로 1개, F의 자식은 H, I로 2개이며 나머지 노드는 자식이 없다. 가장 큰 값이 3이므로 트리의 차수는 3이다.","choices":[{"verdict":"오답","why":"2는 A나 F의 차수다. 트리의 차수는 모든 노드 중 최댓값이므로 B의 3이 된다."},{"verdict":"정답","why":"B가 D, E, F 세 개의 자식을 가져 노드 차수의 최댓값이 3이므로 트리의 차수는 3이다."},{"verdict":"오답","why":"4는 이 트리의 레벨(깊이) 수로, 차수와 다른 개념이다."},{"verdict":"오답","why":"자식이 5개인 노드는 없다. 단말 노드 수(D, E, G, H, I)가 5개인 것과 혼동하면 안 된다."}],"keywords":[{"term":"노드의 차수","desc":"한 노드가 가진 자식(서브트리) 수"},{"term":"트리의 차수","desc":"모든 노드의 차수 중 최댓값"},{"term":"단말 노드","desc":"자식이 없는 노드(Leaf), 차수가 0"}],"memo":"트리의 차수는 '가장 자식 많은 부모'의 자식 수다."}},{"id":"written-2020-3-41","no":41,"unit":"데이터베이스 구축","q":"릴레이션 R의 모든 결정자(determinant)가 후보키이면 그 릴레이션 R은 어떤 정규형에 속하는가?","choices":["제 1 정규형","제 2 정규형","보이스/코드 정규형","제 4 정규형"],"ans":3,"rate":61,"exp":{"concept":"정규화는 릴레이션을 더 작게 나누어 중복과 이상 현상을 없애는 과정이다. 결정자는 다른 속성의 값을 결정하는 속성(X→Y에서 X)이다. 모든 결정자가 후보키인 상태가 보이스-코드 정규형(BCNF)이며, 3정규형을 더 엄격하게 만든 것이다.","choices":[{"verdict":"오답","why":"제1정규형은 모든 속성 값이 원자값(더 쪼갤 수 없는 값)인 상태다."},{"verdict":"오답","why":"제2정규형은 1정규형에서 부분 함수 종속을 제거해 완전 함수 종속을 만족하는 상태다."},{"verdict":"정답","why":"모든 결정자가 후보키인 릴레이션은 보이스/코드 정규형(BCNF)에 속한다."},{"verdict":"오답","why":"제4정규형은 BCNF에서 다치 종속(MVD)을 제거한 상태다."}],"keywords":[{"term":"정규화 순서","desc":"1NF 원자값 → 2NF 부분 종속 제거 → 3NF 이행 종속 제거 → BCNF 결정자가 모두 후보키 → 4NF 다치 종속 제거 → 5NF 조인 종속 제거"},{"term":"결정자","desc":"함수 종속 X→Y에서 Y를 결정하는 X"}],"memo":"정규화는 '도부이결다조'(도메인 원자값·부분·이행·결정자·다치·조인)로 외운다."}},{"id":"written-2020-3-42","no":42,"unit":"데이터베이스 구축","q":"다음 관계형 데이터 모델에 대한 설명으로 옳은 것은?\n<img src=\"data/img/eip_written_20200822_042.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["relation 3개, attribute 3개, tuple 5개","relation 3개, attribute 5개, tuple 3개","relation 1개, attribute 5개, tuple 3개","relation 1개, attribute 3개, tuple 5개"],"ans":4,"rate":69,"exp":{"concept":"관계형 데이터 모델에서 표 하나가 릴레이션(relation), 열(세로)이 속성(attribute), 행(가로)이 튜플(tuple)이다. 그림은 표가 1개이고, 열은 고객ID·고객이름·거주도시 3개, 행은 S1~S5의 5개다.","choices":[{"verdict":"오답","why":"표는 1개이므로 relation이 3개일 수 없다. 속성 수 3을 릴레이션 수로 착각한 보기다."},{"verdict":"오답","why":"표가 1개이고, 속성과 튜플 수도 뒤바뀌어 있다."},{"verdict":"오답","why":"relation 1개는 맞지만 attribute와 tuple 수가 서로 바뀌었다. 열은 3개, 행은 5개다."},{"verdict":"정답","why":"표 1개, 열(고객ID, 고객이름, 거주도시) 3개, 행(S1~S5) 5개이므로 relation 1개, attribute 3개, tuple 5개다."}],"keywords":[{"term":"튜플","desc":"릴레이션의 행, 튜플 수 = 카디널리티(Cardinality)"},{"term":"속성","desc":"릴레이션의 열, 속성 수 = 차수(Degree)"},{"term":"도메인","desc":"하나의 속성이 가질 수 있는 원자값들의 집합"}],"memo":"세로 기둥은 속성(attribute), 가로 줄은 튜플(tuple). 차수는 열 수, 카디널리티는 행 수."}},{"id":"written-2020-3-43","no":43,"unit":"데이터베이스 구축","q":"Commit과 Rollback 명령어에 의해 보장 받는 트랜잭션의 특성은?","choices":["병행성","보안성","원자성","로그"],"ans":3,"rate":65,"wiki":[{"title":"트랜잭션","url":"https://itwiki.kr/w/트랜잭션"},{"title":"트랜잭션 특성","url":"https://itwiki.kr/w/트랜잭션 특성"}],"exp":{"concept":"트랜잭션의 원자성(Atomicity)은 트랜잭션의 연산이 모두 반영되거나 하나도 반영되지 않아야 한다는 성질이다(All or Nothing). 모두 성공하면 COMMIT으로 확정하고, 하나라도 실패하면 ROLLBACK으로 전부 취소해 원자성을 보장한다. 계좌 이체에서 출금만 되고 입금이 안 되는 일을 막는 것이다.","choices":[{"verdict":"오답","why":"병행성은 여러 트랜잭션이 동시에 실행되는 것을 뜻하며 트랜잭션 특성(ACID)에 해당하지 않는다. 동시 실행 간섭을 막는 특성은 고립성(독립성)이다."},{"verdict":"오답","why":"보안성은 트랜잭션의 특성(ACID)에 포함되지 않는다."},{"verdict":"정답","why":"COMMIT과 ROLLBACK으로 '전부 반영 또는 전부 취소'를 보장하는 특성이 원자성이다."},{"verdict":"오답","why":"로그는 회복을 위해 변경 내역을 기록한 파일로, 트랜잭션의 특성이 아니다."}],"keywords":[{"term":"ACID","desc":"원자성(Atomicity), 일관성(Consistency), 독립성(Isolation), 영속성(Durability)"},{"term":"COMMIT","desc":"트랜잭션의 변경 내용을 확정해 DB에 반영"},{"term":"ROLLBACK","desc":"트랜잭션의 변경 내용을 모두 취소하고 이전 상태로 복구"}],"memo":"COMMIT·ROLLBACK은 '전부 아니면 전무'의 원자성과 짝이다."}},{"id":"written-2020-3-44","no":44,"unit":"데이터베이스 구축","q":"관계 데이터베이스인 테이블 R1에 대한 아래 SQL 문의 실행결과로 옳은 것은?\n<div class=\"q-spec\">\n<span class=\"q-spec__label\">보기</span>\n<div class=\"q-tbl-title\">[R1 테이블]</div>\n<table class=\"q-tbl is-data\"><thead><tr><th>학번</th><th>이름</th><th>학년</th><th>학과</th><th>주소</th></tr></thead><tbody><tr><td>1000</td><td>홍길동</td><td>1</td><td>컴퓨터공학</td><td>서울</td></tr><tr><td>2000</td><td>김철수</td><td>1</td><td>전기공학</td><td>경기</td></tr><tr><td>3000</td><td>강남길</td><td>2</td><td>전자공학</td><td>경기</td></tr><tr><td>4000</td><td>오말자</td><td>2</td><td>컴퓨터공학</td><td>경기</td></tr><tr><td>5000</td><td>장미화</td><td>3</td><td>전자공학</td><td>서울</td></tr></tbody></table>\n<pre class=\"q-sql\"><code class=\"language-sql\">SELECT DISTINCT 학년 FROM R1;</code></pre>\n</div>","choices":["<table class=\"q-tbl is-data\"><thead><tr><th>학년</th></tr></thead><tbody><tr><td>1</td></tr><tr><td>1</td></tr><tr><td>2</td></tr><tr><td>2</td></tr><tr><td>3</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>학년</th></tr></thead><tbody><tr><td>1</td></tr><tr><td>2</td></tr><tr><td>3</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>이름</th><th>학년</th></tr></thead><tbody><tr><td>홍길동</td><td>1</td></tr><tr><td>김철수</td><td>1</td></tr><tr><td>강남길</td><td>2</td></tr><tr><td>오말자</td><td>2</td></tr><tr><td>장미화</td><td>3</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>이름</th><th>학년</th></tr></thead><tbody><tr><td>홍길동</td><td>1</td></tr><tr><td>강남길</td><td>2</td></tr><tr><td>장미화</td><td>3</td></tr></tbody></table>"],"ans":2,"rate":79,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"},{"title":"SQL SELECT 구문","url":"https://itwiki.kr/w/SQL SELECT 구문"}],"exp":{"concept":"SELECT DISTINCT는 조회 결과에서 중복된 행을 하나만 남긴다. SELECT 학년이므로 결과에는 학년 열 하나만 나온다. R1의 학년 값은 1, 1, 2, 2, 3이므로 중복을 없애면 1, 2, 3 세 행이 된다.","choices":[{"verdict":"오답","why":"1, 1, 2, 2, 3의 5행은 DISTINCT 없이 SELECT 학년 FROM R1;을 실행한 결과다."},{"verdict":"정답","why":"학년 열만 조회하고 DISTINCT로 중복을 제거하므로 1, 2, 3 세 행이 나온다."},{"verdict":"오답","why":"SELECT 절에 이름을 쓰지 않았으므로 이름 열이 나올 수 없고, 중복도 제거되지 않았다."},{"verdict":"오답","why":"SELECT 절에 이름이 없으므로 이름 열이 결과에 나올 수 없다."}],"keywords":[{"term":"DISTINCT","desc":"조회 결과에서 중복 행을 제거"},{"term":"ALL","desc":"중복을 포함해 모두 조회, SELECT의 기본값"}],"memo":"결과 열은 SELECT 절에 적은 열뿐이다. 먼저 열 모양으로 보기를 거르고, 다음에 중복 여부를 본다."}},{"id":"written-2020-3-45","no":45,"unit":"데이터베이스 구축","q":"DCL(Data Control Language) 명령어가 아닌 것은?","choices":["COMMIT","ROLLBACK","GRANT","SELECT"],"ans":4,"rate":76,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"SQL은 용도에 따라 DDL(정의), DML(조작), DCL(제어)로 나뉜다. DCL은 데이터의 보안·무결성·회복·병행 제어를 위한 언어로 GRANT, REVOKE, COMMIT, ROLLBACK이 있다. SELECT는 데이터를 조회하는 DML이다.","choices":[{"verdict":"오답","why":"COMMIT은 트랜잭션 결과를 확정하는 명령으로 DCL에 포함된다."},{"verdict":"오답","why":"ROLLBACK은 트랜잭션을 취소하고 이전 상태로 되돌리는 명령으로 DCL에 포함된다."},{"verdict":"오답","why":"GRANT는 사용자에게 권한을 부여하는 대표적인 DCL 명령이다."},{"verdict":"정답","why":"SELECT는 데이터를 검색하는 DML(Data Manipulation Language) 명령이다."}],"keywords":[{"term":"DDL","desc":"CREATE, ALTER, DROP"},{"term":"DML","desc":"SELECT, INSERT, UPDATE, DELETE"},{"term":"DCL","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"}],"memo":"DCL은 권한(GRANT·REVOKE)과 트랜잭션 제어(COMMIT·ROLLBACK) 네 개를 묶어 외운다."}},{"id":"written-2020-3-46","no":46,"unit":"데이터베이스 구축","q":"병행제어 기법 중 로킹에 대한 설명으로 옳지 않은 것은?","choices":["로킹의 대상이 되는 객체의 크기를 로킹 단위라고 한다.","데이터베이스, 파일, 레코드 등은 로킹 단위가 될 수 있다.","로킹의 단위가 작아지면 로킹 오버헤드가 증가한다.","로킹의 단위가 커지면 데이터베이스 공유도가 증가한다."],"ans":4,"rate":70,"wiki":[{"title":"데이터베이스 로킹","url":"https://itwiki.kr/w/데이터베이스 로킹"}],"exp":{"concept":"로킹(Locking)은 한 트랜잭션이 데이터를 쓰는 동안 다른 트랜잭션이 접근하지 못하게 잠그는 병행 제어 기법이다. 잠그는 단위가 크면(DB 전체) 관리할 잠금이 적어 오버헤드는 줄지만 다른 사람이 못 쓰는 범위가 넓어져 공유도(병행성)가 낮아진다. 단위가 작으면(레코드) 그 반대다.","choices":[{"verdict":"오답","why":"로킹 대상 객체의 크기를 로킹 단위라고 하는 것은 맞는 설명이다."},{"verdict":"오답","why":"데이터베이스, 파일, 레코드, 필드 등은 모두 로킹 단위가 될 수 있다."},{"verdict":"오답","why":"로킹 단위가 작아지면 관리해야 할 잠금 수가 늘어 오버헤드가 증가하므로 맞는 설명이다."},{"verdict":"정답","why":"로킹 단위가 커지면 한 번에 잠기는 범위가 넓어져 공유도는 감소하므로 틀린 설명이다."}],"keywords":[{"term":"로킹 단위 큼","desc":"로크 수 적음, 오버헤드 감소, 병행성(공유도) 낮음"},{"term":"로킹 단위 작음","desc":"로크 수 많음, 오버헤드 증가, 병행성(공유도) 높음"}],"memo":"방 하나를 통째로 잠그면 관리는 쉽지만 아무도 못 들어온다. 단위가 크면 공유도는 내려간다."}},{"id":"written-2020-3-47","no":47,"unit":"데이터베이스 구축","q":"관계 데이터모델의 무결성 제약 중 기본키 값의 속성 값이 널(Null)값이 아닌 원자 값을 갖는 성질은?","choices":["개체 무결성","참조 무결성","도메인 무결성","튜플의 유일성"],"ans":1,"rate":76,"exp":{"concept":"무결성 제약 조건은 데이터가 정확하고 일관되게 유지되도록 하는 규칙이다. 개체 무결성은 기본키를 이루는 속성 값이 NULL이거나 중복될 수 없다는 규칙이다. 학번이 기본키라면 학번이 비어 있는 학생은 등록될 수 없다.","choices":[{"verdict":"정답","why":"기본키 속성 값이 널이 아닌 원자 값을 가져야 한다는 것은 개체 무결성이다."},{"verdict":"오답","why":"참조 무결성은 외래키 값이 NULL이거나 참조하는 릴레이션의 기본키 값과 같아야 한다는 규칙이다."},{"verdict":"오답","why":"도메인 무결성은 속성 값이 정해진 도메인(허용 범위)에 속해야 한다는 규칙이다."},{"verdict":"오답","why":"튜플의 유일성은 한 릴레이션에 똑같은 튜플이 없다는 릴레이션의 특성으로, 기본키의 NULL 금지를 말하는 무결성 이름이 아니다."}],"keywords":[{"term":"개체 무결성","desc":"기본키는 NULL이나 중복 값을 가질 수 없음"},{"term":"참조 무결성","desc":"외래키 값은 NULL이거나 참조 릴레이션의 기본키 값이어야 함"},{"term":"도메인 무결성","desc":"속성 값은 정의된 도메인 범위 안에 있어야 함"}],"memo":"기본키 = 개체 무결성, 외래키 = 참조 무결성으로 짝지어 외운다."}},{"id":"written-2020-3-48","no":48,"unit":"데이터베이스 구축","q":"뷰(View)의 장점이 아닌 것은?","choices":["뷰 자체로 인덱스를 가짐","데이터 보안 용이","논리적 독립성 제공","사용자 데이터 관리 용이"],"ans":1,"rate":55,"wiki":[{"title":"데이터베이스 뷰","url":"https://itwiki.kr/w/데이터베이스 뷰"}],"exp":{"concept":"뷰(View)는 기본 테이블에서 필요한 부분만 꺼내 만든 가상 테이블이다. 실제 데이터를 저장하지 않으므로 뷰 자체에 인덱스를 만들 수 없다. 대신 필요한 데이터만 보여 주어 보안에 유리하고, 기본 테이블 구조가 바뀌어도 응용 프로그램이 영향을 덜 받는 논리적 독립성을 준다.","choices":[{"verdict":"정답","why":"뷰는 물리적으로 저장되지 않는 가상 테이블이라 자체 인덱스를 가질 수 없다. 이는 뷰의 단점에 해당한다."},{"verdict":"오답","why":"필요한 데이터만 보여 주고 나머지는 숨길 수 있어 데이터 보안이 쉬워지는 것은 뷰의 장점이다."},{"verdict":"오답","why":"기본 테이블이 바뀌어도 뷰 정의만 맞추면 되므로 논리적 독립성을 제공하는 것은 뷰의 장점이다."},{"verdict":"오답","why":"사용자가 필요한 데이터만 다루면 되므로 데이터 관리가 쉬워지는 것은 뷰의 장점이다."}],"keywords":[{"term":"뷰","desc":"기본 테이블에서 유도된 가상 테이블"},{"term":"뷰의 단점","desc":"독자적 인덱스 불가, 정의 변경 불가(ALTER 불가, 삭제 후 재생성), 삽입·삭제·갱신 제약"}],"memo":"뷰는 가상이라 '자기 것'이 없다. 자체 인덱스·자체 저장 공간이 없다."}},{"id":"written-2020-3-49","no":49,"unit":"데이터베이스 구축","q":"분산 데이터베이스의 투명성(Transparency)에 해당 하지 않\n는 것은?","choices":["Location Transparency","Replication Transparency","Failure Transparency","Media Access Transparency"],"ans":4,"rate":63,"wiki":[{"title":"분산 데이터베이스","url":"https://itwiki.kr/w/분산 데이터베이스"}],"exp":{"concept":"분산 데이터베이스는 여러 장소에 흩어진 데이터를 하나의 DB처럼 쓰게 해 준다. 투명성은 사용자가 이 분산 사실을 의식하지 않아도 되게 하는 성질로, 위치·중복(복제)·병행·장애 투명성이 대표적이다.","choices":[{"verdict":"오답","why":"위치 투명성(Location)은 데이터가 실제로 어디에 저장되어 있는지 몰라도 접근할 수 있게 하는 성질이다."},{"verdict":"오답","why":"중복 투명성(Replication)은 데이터가 여러 곳에 복제되어 있어도 하나인 것처럼 사용하게 하는 성질이다."},{"verdict":"오답","why":"장애 투명성(Failure)은 일부 장소나 통신망에 장애가 생겨도 트랜잭션을 정확히 처리하게 하는 성질이다."},{"verdict":"정답","why":"Media Access Transparency는 분산 데이터베이스의 투명성 종류에 포함되지 않는다."}],"keywords":[{"term":"분산 DB 투명성","desc":"위치, 중복(복제), 병행, 장애 투명성"},{"term":"병행 투명성","desc":"여러 트랜잭션이 동시에 실행되어도 결과의 일관성이 유지됨"}],"memo":"분산 DB 투명성은 '위중병장'(위치·중복·병행·장애)으로 외운다."}},{"id":"written-2020-3-50","no":50,"unit":"데이터베이스 구축","q":"정규화의 목적으로 옳지 않은 것은?","choices":["어떠한 릴레이션이라도 데이터베이스 내에서 표현 가능하게 만든다.","데이터 삽입시 릴레이션을 재구성할 필요성을 줄인다.","중복을 배제하여 삽입, 삭제, 갱신 이상의 발생을 야기한다.","효과적인 검색 알고리즘을 생성할 수 있다."],"ans":3,"rate":73,"exp":{"concept":"정규화는 릴레이션을 나누어 데이터 중복을 줄이고, 삽입·삭제·갱신 때 생기는 이상(Anomaly) 현상을 막는 작업이다. 그래서 정규화의 목적은 이상 현상을 없애는 것이지 일으키는 것이 아니다.","choices":[{"verdict":"오답","why":"어떤 릴레이션이라도 데이터베이스 내에서 표현 가능하게 만드는 것은 교재에서 드는 정규화의 목적 중 하나다."},{"verdict":"오답","why":"새 데이터를 삽입할 때 릴레이션을 재구성할 필요성을 줄이는 것은 정규화의 목적이다."},{"verdict":"정답","why":"정규화는 중복을 배제해 삽입·삭제·갱신 이상을 방지하는 것이 목적이므로 이상 발생을 야기한다는 설명은 틀렸다."},{"verdict":"오답","why":"효과적인 검색 알고리즘을 생성할 수 있게 하는 것은 교재에서 드는 정규화의 목적 중 하나다."}],"keywords":[{"term":"정규화","desc":"함수 종속을 기준으로 릴레이션을 분해해 중복과 이상 현상을 제거하는 과정"},{"term":"이상 현상","desc":"삽입 이상, 삭제 이상, 갱신 이상"}],"memo":"보기 문장 끝의 '야기한다'처럼 목적과 반대되는 동사를 끝까지 읽어야 한다."}},{"id":"written-2020-3-51","no":51,"unit":"데이터베이스 구축","q":"다음에 해당하는 함수 종속의 추론 규칙은?\n<img src=\"data/img/eip_written_20200822_051.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["분해 규칙","이행 규칙","반사 규칙","결합 규칙"],"ans":2,"rate":83,"wiki":[{"title":"함수적 종속성","url":"https://itwiki.kr/w/함수적 종속성"}],"exp":{"concept":"함수 종속 X→Y는 X 값이 정해지면 Y 값이 하나로 정해진다는 뜻이다. 암스트롱의 추론 규칙 중 이행 규칙은 X→Y이고 Y→Z이면 X→Z가 성립한다는 규칙이다. 학번이 학과를 정하고 학과가 학과장을 정하면, 학번만 알아도 학과장을 알 수 있는 것과 같다.","choices":[{"verdict":"오답","why":"분해 규칙은 X→YZ이면 X→Y이고 X→Z라는 규칙으로, 오른쪽을 나누는 것이다."},{"verdict":"정답","why":"X→Y이고 Y→Z이면 X→Z가 성립한다는 것이 이행(Transitivity) 규칙이다."},{"verdict":"오답","why":"반사 규칙은 Y가 X의 부분집합이면 X→Y가 성립한다는 규칙이다."},{"verdict":"오답","why":"결합(합집합) 규칙은 X→Y이고 X→Z이면 X→YZ라는 규칙이다."}],"keywords":[{"term":"암스트롱 공리","desc":"반사, 첨가(증가), 이행 규칙이 기본이고 결합·분해·의사이행 규칙은 이로부터 유도됨"},{"term":"이행 규칙","desc":"X→Y, Y→Z이면 X→Z"},{"term":"첨가 규칙","desc":"X→Y이면 XZ→YZ"}],"memo":"A가 B를, B가 C를 정하면 A가 C를 정한다. 다리를 건너듯 '이행'한다."}},{"id":"written-2020-3-52","no":52,"unit":"데이터베이스 구축","q":"다음 R과 S 두 릴레이션에 대한 Division 연산의 수행 결과는?\n<div class=\"q-spec\">\n<span class=\"q-spec__label\">보기</span>\n<div class=\"q-tbl-title\">[릴레이션 R]</div><table class=\"q-tbl is-data\"><thead><tr><th>D1</th><th>D2</th><th>D3</th></tr></thead><tbody><tr><td>a</td><td>1</td><td>A</td></tr><tr><td>b</td><td>1</td><td>A</td></tr><tr><td>c</td><td>2</td><td>A</td></tr><tr><td>d</td><td>2</td><td>B</td></tr></tbody></table>\n<div class=\"q-tbl-title\">[릴레이션 S]</div><table class=\"q-tbl is-data\"><thead><tr><th>D2</th><th>D3</th></tr></thead><tbody><tr><td>1</td><td>A</td></tr></tbody></table>\n</div>","choices":["<table class=\"q-tbl is-data\"><thead><tr><th>D3</th></tr></thead><tbody><tr><td>A</td></tr><tr><td>B</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>D2</th></tr></thead><tbody><tr><td>2</td></tr><tr><td>2</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>D3</th></tr></thead><tbody><tr><td>A</td></tr></tbody></table>","<table class=\"q-tbl is-data\"><thead><tr><th>D1</th></tr></thead><tbody><tr><td>a</td></tr><tr><td>b</td></tr></tbody></table>"],"ans":4,"rate":72,"exp":{"concept":"디비전(Division, ÷) 연산 R÷S는 S의 모든 튜플과 짝을 이루는 R의 나머지 속성 값을 구한다. S는 (D2=1, D3=A) 한 튜플뿐이므로, R에서 (1, A)를 가진 행의 D1 값을 찾으면 된다. a행과 b행이 (1, A)를 가지므로 결과는 D1 속성에 a, b 두 튜플이다.","choices":[{"verdict":"오답","why":"디비전 결과에는 S에 없는 R의 속성(D1)만 남으므로 D3 속성이 결과에 나올 수 없다."},{"verdict":"오답","why":"D2는 S에 포함된 속성이라 결과에서 빠지며, 값 2는 S의 조건 (1, A)와도 맞지 않는다."},{"verdict":"오답","why":"D3는 S에 포함된 속성이므로 결과에 남지 않는다."},{"verdict":"정답","why":"S의 튜플 (1, A)를 모두 가지고 있는 R의 D1 값은 a와 b이므로 결과는 D1 = a, b다."}],"keywords":[{"term":"Division(÷)","desc":"R÷S, S의 모든 튜플과 관련 있는 R의 튜플에서 S의 속성을 뺀 나머지 속성만 구함"},{"term":"순수 관계 연산자","desc":"Select(σ), Project(π), Join(⋈), Division(÷)"}],"memo":"디비전 결과의 속성은 'R의 속성 - S의 속성'이다. 결과 열 이름부터 확인하면 보기가 바로 걸러진다."}},{"id":"written-2020-3-53","no":53,"unit":"데이터베이스 구축","q":"player 테이블에는 player_name, team_id, height 컬럼이 존재한다. 아래 SQL문에서 문법적 오류가 있는 부분은?\n<img src=\"data/img/eip_written_20200822_053.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["(1)","(2)","(3)","(4)"],"ans":4,"rate":76,"wiki":[{"title":"데이터베이스","url":"https://itwiki.kr/w/데이터베이스"}],"exp":{"concept":"BETWEEN은 'BETWEEN 값1 AND 값2' 형태로 쓰며 값1 이상 값2 이하를 뜻한다. 여기서 AND는 BETWEEN 구문의 일부이므로 OR로 바꿀 수 없다. (4)의 BETWEEN 170 or 180은 문법 오류이고, 올바른 표현은 BETWEEN 170 AND 180이다.","choices":[{"verdict":"오답","why":"SELECT player_name, height는 조회할 컬럼을 쉼표로 나열한 올바른 문장이다."},{"verdict":"오답","why":"FROM player는 조회 대상 테이블을 지정한 올바른 문장이다."},{"verdict":"오답","why":"WHERE team_id = 'Korea'는 문자열 조건을 작은따옴표로 비교한 올바른 문장이다."},{"verdict":"정답","why":"BETWEEN은 반드시 AND와 짝을 이루어야 하므로 BETWEEN 170 or 180은 문법 오류다."}],"keywords":[{"term":"BETWEEN a AND b","desc":"a 이상 b 이하, height >= 170 AND height <= 180과 같음"},{"term":"IN","desc":"IN (값1, 값2), 나열한 값 중 하나와 같으면 참"}],"memo":"BETWEEN 뒤에는 무조건 AND. BETWEEN은 경계값을 포함한다는 것도 함께 외운다."}},{"id":"written-2020-3-54","no":54,"unit":"데이터베이스 구축","q":"데이터베이스 로그(log)를 필요로 하는 회복 기법은?","choices":["즉각 갱신 기법","대수적 코딩 방법","타임 스탬프 기법","폴딩 기법"],"ans":1,"rate":48,"wiki":[{"title":"데이터베이스 회복","url":"https://itwiki.kr/w/데이터베이스 회복"}],"exp":{"concept":"회복(Recovery)은 장애가 났을 때 데이터베이스를 장애 전의 올바른 상태로 되돌리는 것이다. 즉각 갱신 기법은 트랜잭션이 끝나기 전에도 변경 내용을 바로 DB에 반영하므로, 실패하면 되돌리고(UNDO) 다시 하기(REDO) 위해 변경 전후 값을 담은 로그가 반드시 필요하다.","choices":[{"verdict":"정답","why":"즉각 갱신 기법은 변경 내용을 즉시 DB에 반영하고 로그를 이용해 UNDO와 REDO로 회복하는 로그 기반 회복 기법이다."},{"verdict":"오답","why":"대수적 코딩 방법은 키 값의 각 자리 비트를 다항식의 계수로 보고, 해시표 크기로 정한 다항식으로 나눈 나머지로 주소를 구하는 해싱 함수 기법이다. 회복 기법이 아니다."},{"verdict":"오답","why":"타임 스탬프 기법은 트랜잭션에 시간 순서를 붙여 실행 순서를 정하는 병행 제어 기법이다."},{"verdict":"오답","why":"폴딩 기법은 키를 여러 부분으로 나누어 더하거나 XOR해 주소를 구하는 해싱 함수 기법이다."}],"keywords":[{"term":"즉각 갱신","desc":"변경을 즉시 DB에 반영, 회복 시 UNDO와 REDO 모두 사용"},{"term":"지연 갱신","desc":"커밋 후에 DB에 반영, 회복 시 REDO만 사용"},{"term":"회복 기법","desc":"로그 기반(즉각·지연 갱신), 검사점(Checkpoint), 그림자 페이징(Shadow Paging)"}],"memo":"그림자 페이징은 로그를 쓰지 않는 회복 기법이라는 점이 반대로 자주 출제된다."}},{"id":"written-2020-3-55","no":55,"unit":"데이터베이스 구축","q":"DML(Data Manipulation Language) 명령어가 아닌 것은?","choices":["INSERT","UPDATE","ALTER","DELETE"],"ans":3,"rate":77,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"DML(데이터 조작어)은 테이블 안의 데이터를 조회·삽입·수정·삭제하는 명령이다. 반면 ALTER는 테이블 구조 자체를 바꾸는 DDL(데이터 정의어)이다. 집에 비유하면 DML은 가구를 넣고 빼는 것이고, DDL은 벽을 세우거나 허무는 것이다.","choices":[{"verdict":"오답","why":"INSERT는 새 행을 삽입하는 DML 명령이다."},{"verdict":"오답","why":"UPDATE는 기존 행의 값을 수정하는 DML 명령이다."},{"verdict":"정답","why":"ALTER는 테이블의 구조(컬럼 추가·변경·삭제 등)를 바꾸는 DDL 명령이다."},{"verdict":"오답","why":"DELETE는 행을 삭제하는 DML 명령이다."}],"keywords":[{"term":"DDL","desc":"CREATE, ALTER, DROP (TRUNCATE 포함)"},{"term":"DML","desc":"SELECT, INSERT, UPDATE, DELETE"},{"term":"DCL","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"}],"memo":"DELETE(DML, 데이터 삭제)와 DROP(DDL, 구조 삭제)를 헷갈리지 말 것."}},{"id":"written-2020-3-56","no":56,"unit":"데이터베이스 구축","q":"다음과 같이 위쪽 릴레이션을 아래쪽 릴레이션으로 정규화를 하였을 때 어떤 정규화 작업을 한 것인가?\n<img src=\"data/img/eip_written_20200822_056.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["제1정규형","제2정규형","제3정규형","제4정규형"],"ans":1,"rate":70,"exp":{"concept":"제1정규형(1NF)은 모든 속성 값이 더 쪼갤 수 없는 원자값이어야 한다는 조건이다. 위쪽 표는 대한민국의 도시 칸에 '서울, 부산'처럼 값이 두 개 들어 있어 원자값이 아니다. 이를 한 칸에 하나씩 들어가도록 행을 나눈 아래쪽 표가 제1정규형이다.","choices":[{"verdict":"정답","why":"하나의 칸에 여러 값(서울, 부산 / 워싱턴, 뉴욕)이 있던 것을 원자값으로 나누었으므로 제1정규형으로 만든 작업이다."},{"verdict":"오답","why":"제2정규형은 부분 함수 종속을 제거하는 작업으로, 이 표처럼 반복 값을 쪼개는 작업이 아니다."},{"verdict":"오답","why":"제3정규형은 이행 함수 종속을 제거하는 작업이다."},{"verdict":"오답","why":"제4정규형은 다치 종속을 제거하는 작업이다."}],"keywords":[{"term":"제1정규형","desc":"모든 도메인이 원자값으로만 구성"},{"term":"원자값","desc":"더 이상 나눌 수 없는 하나의 값"}],"memo":"한 칸에 쉼표로 여러 값이 있다가 줄이 늘어나면 1정규화다."}},{"id":"written-2020-3-57","no":57,"unit":"데이터베이스 구축","q":"관계대수의 순수관계 연산자가 아닌 것은?","choices":["Select","Cartesian Product","Division","Project"],"ans":2,"rate":65,"wiki":[{"title":"관계대수","url":"https://itwiki.kr/w/관계대수"}],"exp":{"concept":"관계대수 연산자는 일반 집합 연산자와 순수 관계 연산자로 나뉜다. 순수 관계 연산자는 릴레이션 구조를 위해 따로 만든 Select, Project, Join, Division이다. 카티션 프로덕트는 수학의 집합 연산을 그대로 가져온 일반 집합 연산자다.","choices":[{"verdict":"오답","why":"Select(σ)는 조건에 맞는 튜플(행)을 고르는 순수 관계 연산자다."},{"verdict":"정답","why":"Cartesian Product(×)는 두 릴레이션의 모든 튜플을 조합하는 일반 집합 연산자다."},{"verdict":"오답","why":"Division(÷)은 순수 관계 연산자다."},{"verdict":"오답","why":"Project(π)는 원하는 속성(열)만 추출하는 순수 관계 연산자다."}],"keywords":[{"term":"순수 관계 연산자","desc":"Select(σ), Project(π), Join(⋈), Division(÷)"},{"term":"일반 집합 연산자","desc":"합집합(∪), 교집합(∩), 차집합(−), 카티션 프로덕트(×)"}],"memo":"순수 관계 연산자는 'SPJD'(Select·Project·Join·Division) 네 개뿐이다."}},{"id":"written-2020-3-58","no":58,"unit":"데이터베이스 구축","q":"다음 중 SQL의 집계 함수(aggregation function)가 아닌 것은?","choices":["AVG","COUNT","SUM","CREATE"],"ans":4,"rate":91,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"집계 함수는 여러 행의 값을 모아 하나의 결과로 계산하는 함수다. 개수를 세는 COUNT, 합계 SUM, 평균 AVG, 최댓값 MAX, 최솟값 MIN 등이 있다. CREATE는 테이블 같은 객체를 만드는 DDL 명령이다.","choices":[{"verdict":"오답","why":"AVG는 평균을 구하는 집계 함수다."},{"verdict":"오답","why":"COUNT는 행의 개수를 세는 집계 함수다."},{"verdict":"오답","why":"SUM은 합계를 구하는 집계 함수다."},{"verdict":"정답","why":"CREATE는 테이블·뷰·인덱스 등을 정의하는 DDL 명령으로 집계 함수가 아니다."}],"keywords":[{"term":"집계 함수","desc":"COUNT, SUM, AVG, MAX, MIN, STDDEV, VARIANCE"},{"term":"GROUP BY","desc":"지정한 컬럼 값으로 그룹을 묶어 그룹별로 집계 함수 적용"}],"memo":"집계 함수는 숫자를 모아 하나로 만드는 것, CREATE는 구조를 만드는 명령."}},{"id":"written-2020-3-59","no":59,"unit":"데이터베이스 구축","q":"릴레이션 조작 시 데이터들이 불필요하게 중복되어 예기치 않게 발생하는 곤란한 현상을 의미하는 것은?","choices":["normalization","rollback","cardinality","anomaly"],"ans":4,"rate":70,"exp":{"concept":"이상(Anomaly)은 정규화가 덜 된 릴레이션에서 데이터 중복 때문에 삽입·삭제·갱신할 때 생기는 곤란한 현상이다. 예를 들어 같은 정보가 여러 행에 있는데 한 곳만 고치면 데이터가 서로 달라지는 것이 갱신 이상이다.","choices":[{"verdict":"오답","why":"normalization(정규화)은 이상 현상을 없애기 위해 릴레이션을 분해하는 과정이다."},{"verdict":"오답","why":"rollback(롤백)은 트랜잭션의 변경을 취소해 이전 상태로 되돌리는 명령이다."},{"verdict":"오답","why":"cardinality(카디널리티)는 릴레이션의 튜플(행) 수다."},{"verdict":"정답","why":"데이터 중복으로 조작 시 예기치 않게 생기는 곤란한 현상을 anomaly(이상)라고 한다."}],"keywords":[{"term":"삽입 이상","desc":"원하지 않는 값까지 함께 넣어야 삽입할 수 있는 현상"},{"term":"삭제 이상","desc":"한 튜플을 지울 때 필요한 정보까지 함께 지워지는 현상"},{"term":"갱신 이상","desc":"중복 데이터 중 일부만 수정되어 불일치가 생기는 현상"}],"memo":"이상 현상은 '삽삭갱'(삽입·삭제·갱신) 세 가지다."}},{"id":"written-2020-3-60","no":60,"unit":"데이터베이스 구축","q":"릴레이션에 대한 설명으로 거리가 먼 것은?","choices":["튜플들의 삽입, 삭제 등의 작업으로 인해 릴레이션은 시간에 따라 변한다.","한 릴레이션에 포함된 튜플들은 모두 상이하다.","애트리뷰트는 논리적으로 쪼갤 수 없는 원자값으로 저장한다.","한 릴레이션에 포함된 튜플 사이에는 순서가 있다."],"ans":4,"rate":70,"exp":{"concept":"릴레이션(테이블)은 몇 가지 특성을 가진다. 똑같은 튜플이 없고(유일성), 튜플 사이와 속성 사이에 순서가 없으며, 속성 값은 원자값이고, 삽입·삭제로 시간에 따라 내용이 변한다. 행을 어떤 순서로 보여 주든 같은 릴레이션이다.","choices":[{"verdict":"오답","why":"튜플 삽입·삭제로 릴레이션의 내용이 계속 바뀌는 것은 릴레이션의 특성이다."},{"verdict":"오답","why":"한 릴레이션의 튜플은 모두 달라야 한다는 튜플의 유일성은 맞는 설명이다."},{"verdict":"오답","why":"속성 값은 더 쪼갤 수 없는 원자값이어야 한다는 것은 맞는 설명이다."},{"verdict":"정답","why":"릴레이션의 튜플 사이에는 순서가 없으므로 순서가 있다는 설명은 틀렸다."}],"keywords":[{"term":"릴레이션 특성","desc":"튜플 유일성, 튜플 무순서, 속성 무순서, 속성 원자값, 시간에 따라 변함"},{"term":"릴레이션 스키마","desc":"릴레이션의 이름과 속성들의 집합, 즉 구조(틀)"},{"term":"릴레이션 인스턴스","desc":"어느 시점에 릴레이션에 들어 있는 튜플들의 집합"}],"memo":"릴레이션은 집합이다. 집합에는 중복도 순서도 없다."}},{"id":"written-2020-3-61","no":61,"unit":"프로그래밍 언어 활용","q":"다음 자바 프로그램 조건문에 대해 삼항 조건 연산자를 사용하여 옳게 나타낸 것은?\n<img src=\"data/img/eip_written_20200822_061.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["int i = 7, j = 9;int k;k = (i＞j)?(i – j):(i + j);","int i = 7, j = 9;int k;k = (i＜j)?(i – j):(i + j);","int i = 7, j = 9;int k;k = (i＞j)?(i + j):(i - j);","int i = 7, j = 9;int k;k = (i＜j)?(i + j):(i - j);"],"ans":1,"rate":87,"exp":{"concept":"삼항 조건 연산자는 '조건 ? 참일 때 값 : 거짓일 때 값' 형태다. 지문의 if문은 i > j이면 k = i - j, 아니면 k = i + j이므로 그대로 옮기면 k = (i > j) ? (i - j) : (i + j)다. i = 7, j = 9에서 i > j는 거짓이므로 k = 7 + 9 = 16이다.","choices":[{"verdict":"정답","why":"조건 i > j, 참일 때 i - j, 거짓일 때 i + j로 if문과 똑같이 옮겼다. i=7, j=9이면 k=16이다."},{"verdict":"오답","why":"조건이 i < j로 바뀌어 i=7, j=9에서 참이 되므로 k = 7 - 9 = -2가 되어 if문 결과와 다르다."},{"verdict":"오답","why":"참과 거짓의 값이 뒤바뀌어 i > j가 거짓일 때 i - j를 계산하므로 k = -2가 된다."},{"verdict":"오답","why":"이 값에서는 k=16이 나오지만, i와 j가 같을 때 if문은 i + j, 이 식은 i - j를 계산하므로 if문을 옳게 옮긴 것이 아니다."}],"keywords":[{"term":"삼항 조건 연산자","desc":"조건 ? 값1 : 값2, 조건이 참이면 값1, 거짓이면 값2"},{"term":"if-else 변환","desc":"if의 조건은 ? 앞, if 블록 값은 : 앞, else 블록 값은 : 뒤"}],"memo":"if 조건을 바꾸지 말고 그대로 ? 앞에 쓰고, if 쪽 값을 먼저, else 쪽 값을 뒤에 쓴다."}},{"id":"written-2020-3-62","no":62,"unit":"프로그래밍 언어 활용","q":"다음 내용이 설명하는 소프트웨어 취약점은?\n<img src=\"data/img/eip_written_20200822_062.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["FTP 바운스 공격","SQL 삽입","버퍼 오버플로","디렉토리 접근 공격"],"ans":3,"rate":77,"wiki":[{"title":"버퍼 오버플로우","url":"https://itwiki.kr/w/버퍼 오버플로우"}],"exp":{"concept":"버퍼 오버플로(Buffer Overflow)는 정해진 크기의 메모리 공간(버퍼)보다 더 많은 데이터를 넣어 옆의 메모리를 덮어쓰게 되는 취약점이다. 이로 인해 프로그램이 잘못 동작하거나, 공격자가 넣은 코드가 실행될 수 있다. 컵에 물을 넘치게 부으면 탁자까지 젖는 것과 같다.","choices":[{"verdict":"오답","why":"FTP 바운스 공격은 FTP 서버의 PORT 명령을 악용해 FTP 서버를 거쳐 다른 호스트를 포트 스캔하거나 데이터를 보내는 공격이다."},{"verdict":"오답","why":"SQL 삽입은 입력값에 SQL 구문을 넣어 데이터베이스를 비정상적으로 조작하는 취약점이다."},{"verdict":"정답","why":"메모리를 다루는 데 오류가 생겨 잘못된 동작을 하게 되는 취약점은 버퍼 오버플로다."},{"verdict":"오답","why":"디렉터리 접근 공격은 경로를 조작해 허가되지 않은 디렉터리나 파일에 접근하는 공격으로, 메모리 오류와는 관계가 없다."}],"keywords":[{"term":"버퍼 오버플로","desc":"버퍼 크기를 넘는 데이터 입력으로 인접 메모리를 덮어쓰는 취약점"},{"term":"대응 방법","desc":"입력 길이 검사, 안전한 함수(strncpy 등) 사용, 스택 가드, ASLR"}],"memo":"'메모리'와 '오류'가 함께 나오면 버퍼 오버플로."}},{"id":"written-2020-3-63","no":63,"unit":"프로그래밍 언어 활용","q":"다음 중 bash 쉘 스크립트에서 사용할 수 있는 제어문이 아닌 것은?","choices":["if","for","repeat_do","while"],"ans":3,"rate":83,"exp":{"concept":"bash 쉘 스크립트는 조건과 반복을 위한 제어문으로 if, case, for, while, until, select를 제공한다. repeat_do라는 제어문은 bash에 없다.","choices":[{"verdict":"오답","why":"if는 조건에 따라 명령을 실행하는 bash 제어문이다(if ... then ... fi)."},{"verdict":"오답","why":"for는 목록의 값을 하나씩 꺼내 반복하는 bash 제어문이다(for ... do ... done)."},{"verdict":"정답","why":"repeat_do는 bash에서 제공하지 않는 제어문이다."},{"verdict":"오답","why":"while은 조건이 참인 동안 반복하는 bash 제어문이다(while ... do ... done)."}],"keywords":[{"term":"bash 제어문","desc":"if, case, for, while, until, select"},{"term":"until","desc":"조건이 거짓인 동안 반복(참이 되면 종료)"}],"memo":"bash 반복문은 for, while, until 세 개만 기억하면 repeat 류 함정이 걸러진다."}},{"id":"written-2020-3-64","no":64,"unit":"프로그래밍 언어 활용","q":"IPv6에 대한 설명으로 틀린 것은?","choices":["32비트의 주소체계를 사용한다.","멀티미디어의 실시간 처리가 가능하다.","IPv4보다 보안성이 강화되었다.","자동으로 네트워크 환경구성이 가능하다."],"ans":1,"rate":84,"wiki":[{"title":"IPv6","url":"https://itwiki.kr/w/IPv6"}],"exp":{"concept":"IPv6는 IPv4의 주소 부족 문제를 해결하려고 만든 인터넷 프로토콜이다. 주소 길이가 IPv4의 32비트에서 128비트로 늘었고, 16비트씩 8부분으로 나누어 16진수로 표기한다. 자동 주소 설정, IPSec 기반의 보안 강화, 흐름 레이블을 이용한 실시간 처리 지원 등의 특징이 있다.","choices":[{"verdict":"정답","why":"32비트 주소 체계는 IPv4다. IPv6는 128비트 주소 체계를 사용한다."},{"verdict":"오답","why":"IPv6는 흐름 레이블(Flow Label) 등으로 멀티미디어의 실시간 처리를 지원하므로 맞는 설명이다."},{"verdict":"오답","why":"IPv6는 IPSec 등 보안 기능을 기본으로 고려해 IPv4보다 보안이 강화되었다."},{"verdict":"오답","why":"IPv6는 주소 자동 구성 기능(플러그 앤 플레이)을 지원하므로 맞는 설명이다."}],"keywords":[{"term":"IPv6","desc":"128비트, 16비트씩 8개 필드, 16진수와 콜론(:)으로 표기"},{"term":"IPv4","desc":"32비트, 8비트씩 4개 필드, 10진수와 점(.)으로 표기"},{"term":"IPv6 주소 유형","desc":"유니캐스트, 멀티캐스트, 애니캐스트 (브로드캐스트 없음)"}],"memo":"IPv4는 32비트, IPv6는 그 4배인 128비트."}},{"id":"written-2020-3-65","no":65,"unit":"프로그래밍 언어 활용","q":"효과적인 모듈 설계를 위한 유의사항으로 거리가 먼 것은?","choices":["모듈간의 결합도를 약하게 하면 모듈 독립성이 향상된다.","복잡도와 중복성을 줄이고 일관성을 유지시킨다.","모듈의 기능은 예측이 가능해야 하며 지나치게 제한적 이여야 한다.","유지보수가 용이해야 한다."],"ans":3,"rate":90,"wiki":[{"title":"소프트웨어_모듈화","url":"https://itwiki.kr/w/소프트웨어_모듈화"}],"exp":{"concept":"좋은 모듈은 서로 덜 엮이고(결합도 낮음) 내부는 잘 뭉쳐 있어야(응집도 높음) 독립성이 높다. 또 모듈의 기능은 예측 가능해야 하지만 지나치게 제한적이면 재사용이 어려우므로 피해야 한다.","choices":[{"verdict":"오답","why":"결합도를 약하게 하면 모듈 독립성이 높아지는 것은 맞는 유의사항이다."},{"verdict":"오답","why":"복잡도와 중복을 줄이고 일관성을 유지하는 것은 맞는 유의사항이다."},{"verdict":"정답","why":"모듈 기능은 예측 가능해야 하지만 지나치게 제한적이어서는 안 되므로 '제한적이어야 한다'는 틀린 설명이다."},{"verdict":"오답","why":"유지보수가 쉬워야 한다는 것은 맞는 유의사항이다."}],"keywords":[{"term":"모듈 독립성","desc":"결합도는 약하게, 응집도는 강하게 할수록 높아짐"},{"term":"결합도","desc":"모듈과 모듈 사이의 상호 의존 정도"},{"term":"응집도","desc":"한 모듈 내부 요소들이 서로 관련된 정도"}],"memo":"결합도는 낮게, 응집도는 높게. '지나치게'가 붙은 보기는 의심한다."}},{"id":"written-2020-3-66","no":66,"unit":"프로그래밍 언어 활용","q":"HRN 방식으로 스케줄링 할 경우, 입력된 작업이 다음과 같을 때 처리되는 작업 순서로 옳은 것은?\n<img src=\"data/img/eip_written_20200822_066.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["A→B→C→D","A→C→B→D","D→B→C→A","D→A→B→C"],"ans":3,"rate":61,"wiki":[{"title":"HRRN_스케줄링","url":"https://itwiki.kr/w/HRRN_스케줄링"}],"exp":{"concept":"HRN(Highest Response-ratio Next)은 실행 시간이 긴 작업이 계속 밀리는 SJF의 단점을 보완한 비선점 스케줄링이다. 우선순위 = (대기 시간 + 서비스 시간) / 서비스 시간이며 값이 클수록 먼저 실행한다. A = (5+20)/20 = 1.25, B = (40+20)/20 = 3, C = (15+45)/45 ≈ 1.33, D = (20+2)/2 = 11이므로 D → B → C → A 순서다.","choices":[{"verdict":"오답","why":"단순히 작업 이름 순서로, 우선순위가 가장 낮은 A(1.25)가 먼저 실행될 수 없다."},{"verdict":"오답","why":"A(1.25)가 가장 먼저 오고 C가 B보다 앞서 있어 우선순위 계산과 맞지 않는다."},{"verdict":"정답","why":"우선순위가 D(11) > B(3) > C(약 1.33) > A(1.25)이므로 D → B → C → A 순서다."},{"verdict":"오답","why":"D 다음으로 A를 두었지만 A의 우선순위(1.25)는 가장 낮다."}],"keywords":[{"term":"HRN 우선순위","desc":"(대기 시간 + 서비스 시간) / 서비스 시간, 클수록 먼저"},{"term":"SJF","desc":"실행 시간이 가장 짧은 작업을 먼저 처리하는 비선점 스케줄링"},{"term":"에이징(Aging)","desc":"오래 기다린 작업의 우선순위를 높여 무한 대기를 막는 기법"}],"memo":"HRN 분모는 서비스 시간이다. 분모를 대기 시간으로 쓰는 실수가 잦다.","doubt":"HRN을 엄밀히 적용하면 작업 하나가 끝날 때마다 늘어난 대기 시간으로 우선순위를 다시 계산해야 한다. 그러면 D(서비스 시간 2)가 끝난 뒤에도 B가 3.1로 가장 높아 B가 실행되고, D와 B가 끝난 시점(시간 22 경과)에는 A가 (27+20)/20 = 2.35, C가 (37+45)/45 ≈ 1.82가 되어 D→B→A→C 순서가 된다. 이 순서는 보기에 없으므로, 출제 의도는 처음 주어진 대기 시간으로 한 번만 계산하는 방식이며 정답 3번은 그 기준에서 맞다."}},{"id":"written-2020-3-67","no":67,"unit":"프로그래밍 언어 활용","q":"운영체제에 대한 설명으로 거리가 먼 것은?","choices":["다중 사용자와 다중 응용프로그램 환경하에서 자원의 현재 상태를 파악하고 자원 분배를 위한 스케줄링을 담당한다.","CPU, 메모리 공간, 기억 장치, 입출력 장치 등의 자원을 관리한다.","운영체제의 종류로는 매크로 프로세서, 어셈블러, 컴파일러 등이 있다.","입출력 장치와 사용자 프로그램을 제어한다."],"ans":3,"rate":75,"wiki":[{"title":"운영체제","url":"https://itwiki.kr/w/운영체제"}],"exp":{"concept":"운영체제(OS)는 컴퓨터의 CPU, 메모리, 저장 장치, 입출력 장치 같은 자원을 관리하고 사용자와 하드웨어 사이에서 인터페이스 역할을 하는 시스템 소프트웨어다. 종류로는 Windows, UNIX, Linux, macOS, MS-DOS 등이 있다. 매크로 프로세서, 어셈블러, 컴파일러는 언어 번역·처리 프로그램이다.","choices":[{"verdict":"오답","why":"자원 상태를 파악하고 자원 분배를 위한 스케줄링을 담당하는 것은 운영체제의 역할이다."},{"verdict":"오답","why":"CPU, 메모리, 기억 장치, 입출력 장치 등 자원 관리는 운영체제의 핵심 기능이다."},{"verdict":"정답","why":"매크로 프로세서, 어셈블러, 컴파일러는 프로그램을 번역·처리하는 언어 처리 프로그램이지 운영체제의 종류가 아니다."},{"verdict":"오답","why":"입출력 장치와 사용자 프로그램을 제어하는 것은 운영체제의 역할이다."}],"keywords":[{"term":"운영체제","desc":"자원 관리와 사용자-하드웨어 간 인터페이스를 제공하는 시스템 소프트웨어"},{"term":"운영체제 성능 평가 기준","desc":"처리 능력, 반환 시간, 사용 가능도, 신뢰도"},{"term":"언어 번역 프로그램","desc":"어셈블러, 컴파일러, 인터프리터"}],"memo":"운영체제의 '종류'는 Windows·UNIX·Linux 같은 제품 이름이다. 번역기는 운영체제가 아니다."}},{"id":"written-2020-3-68","no":68,"unit":"프로그래밍 언어 활용","q":"배치 프로그램의 필수 요소에 대한 설명으로 틀린 것은?","choices":["자동화는 심각한 오류 상황 외에는 사용자의 개입 없이 동작해야 한다.","안정성은 어떤 문제가 생겼는지, 언제 발생했는지 등을 추적할 수 있어야 한다.","대용량 데이터는 대용량의 데이터를 처리할 수 있어야 한다.","무결성은 주어진 시간 내에 처리를 완료할 수 있어야 하고, 동시에 동작하고 있는 다른 애플리케이션을 방해하지 말아야 한다."],"ans":4,"rate":61,"exp":{"concept":"배치 프로그램은 사용자 개입 없이 정해진 시간에 데이터를 모아 한꺼번에 처리하는 프로그램이다. 필수 요소는 대용량 데이터, 자동화, 견고성, 안정성(신뢰성), 성능이다. 주어진 시간 안에 처리를 끝내고 다른 애플리케이션을 방해하지 않아야 한다는 것은 성능에 대한 설명이다.","choices":[{"verdict":"오답","why":"심각한 오류 상황 외에는 사용자 개입 없이 동작해야 한다는 것은 자동화의 올바른 설명이다."},{"verdict":"오답","why":"어떤 문제가 언제 발생했는지 추적할 수 있어야 한다는 것은 안정성의 올바른 설명이다."},{"verdict":"오답","why":"대용량 데이터를 처리할 수 있어야 한다는 것은 대용량 데이터 요소의 올바른 설명이다."},{"verdict":"정답","why":"주어진 시간 내 처리 완료와 다른 애플리케이션을 방해하지 않는 것은 성능에 대한 설명이며, 무결성은 배치 프로그램 필수 요소에 포함되지 않는다."}],"keywords":[{"term":"배치 프로그램 필수 요소","desc":"대용량 데이터, 자동화, 견고성, 안정성(신뢰성), 성능"},{"term":"견고성","desc":"잘못된 데이터나 중복 데이터 등 비정상 상황에서도 중단 없이 수행"},{"term":"배치 스케줄러","desc":"스프링 배치(Spring Batch), Quartz, Cron 등"}],"memo":"'주어진 시간 안에' 처리는 성능이다. 이름과 설명을 짝지어 바꿔 놓은 보기를 조심한다."}},{"id":"written-2020-3-69","no":69,"unit":"프로그래밍 언어 활용","q":"TCP 프로토콜에 대한 설명으로 거리가 먼 것은?","choices":["신뢰성이 있는 연결 지향형 전달 서비스이다.","기본 헤더 크기는 100byte이고 160byte까지 확장 가능하다.","스트림 전송 기능을 제공한다.","순서제어, 오류제어, 흐름제어 기능을 제공한다."],"ans":2,"rate":71,"wiki":[{"title":"TCP","url":"https://itwiki.kr/w/TCP"}],"exp":{"concept":"TCP(Transmission Control Protocol)는 전송 계층의 연결 지향형 프로토콜로, 데이터가 순서대로 빠짐없이 도착하도록 보장한다. 헤더의 기본 크기는 20바이트이고 옵션을 포함해 최대 60바이트까지 늘어날 수 있다.","choices":[{"verdict":"오답","why":"TCP는 신뢰성 있는 연결 지향형 전송 서비스를 제공하므로 맞는 설명이다."},{"verdict":"정답","why":"TCP 헤더의 기본 크기는 20바이트이고 최대 60바이트까지 확장되므로 100바이트·160바이트는 틀렸다."},{"verdict":"오답","why":"TCP는 데이터를 바이트의 연속인 스트림으로 전송하므로 맞는 설명이다."},{"verdict":"오답","why":"TCP는 순서 제어, 오류 제어, 흐름 제어 기능을 제공하므로 맞는 설명이다."}],"keywords":[{"term":"TCP","desc":"연결 지향, 신뢰성 보장, 헤더 20~60바이트"},{"term":"UDP","desc":"비연결형, 신뢰성 보장 안 함, 헤더 8바이트로 빠름"}],"memo":"TCP 헤더는 20에서 60, UDP 헤더는 8바이트."}},{"id":"written-2020-3-70","no":70,"unit":"프로그래밍 언어 활용","q":"다음이 설명하는 응집도의 유형은?\n<img src=\"data/img/eip_written_20200822_070.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["기능적 응집도","우연적 응집도","논리적 응집도","절차적 응집도"],"ans":4,"rate":80,"wiki":[{"title":"응집도","url":"https://itwiki.kr/w/응집도"}],"exp":{"concept":"응집도는 모듈 안의 구성 요소들이 얼마나 하나의 목적으로 뭉쳐 있는지를 나타낸다. 절차적 응집도는 모듈이 여러 관련 기능을 가지고 있고, 모듈 안의 구성 요소들이 그 기능들을 정해진 순서대로 수행하는 경우다.","choices":[{"verdict":"오답","why":"기능적 응집도는 모듈의 모든 요소가 단일 기능을 수행하기 위해 모여 있는 경우로 가장 강한 응집도다."},{"verdict":"오답","why":"우연적 응집도는 서로 관련 없는 요소들이 우연히 한 모듈에 모인 경우로 가장 약한 응집도다."},{"verdict":"오답","why":"논리적 응집도는 비슷한 성격이나 형태의 처리 요소들을 한 모듈에 모은 경우다."},{"verdict":"정답","why":"다수의 관련 기능을 가진 모듈에서 구성 요소들이 그 기능을 순차적으로 수행하는 경우가 절차적 응집도다."}],"keywords":[{"term":"응집도 순서(강→약)","desc":"기능적 > 순차적 > 교환(통신)적 > 절차적 > 시간적 > 논리적 > 우연적"},{"term":"순차적 응집도","desc":"한 활동의 출력 데이터를 다음 활동의 입력으로 사용"},{"term":"시간적 응집도","desc":"특정 시간에 처리되어야 하는 활동들을 한 모듈에 모음"}],"memo":"응집도는 '기순교절시논우'로 강한 것부터 외운다. 출력이 입력으로 이어지면 순차적, 순서대로 수행만 하면 절차적."}},{"id":"written-2020-3-71","no":71,"unit":"프로그래밍 언어 활용","q":"OSI-7Layer에서 링크의 설정과 유지 및 종료를 담당하며, 노드간의 오류제어와 흐름제어 기능을 수행하는 계층은?","choices":["데이터링크 계층","물리 계층","세션 계층","응용 계층"],"ans":1,"rate":72,"wiki":[{"title":"OSI 7계층","url":"https://itwiki.kr/w/OSI 7계층"}],"exp":{"concept":"OSI 7계층 중 데이터 링크 계층(2계층)은 바로 이웃한 두 노드 사이에서 데이터를 안전하게 전달하는 일을 맡는다. 링크를 설정·유지·종료하고, 프레임 단위로 오류 제어와 흐름 제어를 한다. 대표 장비는 스위치와 브리지다.","choices":[{"verdict":"정답","why":"링크의 설정·유지·종료와 노드 간 오류 제어·흐름 제어를 담당하는 계층은 데이터 링크 계층이다."},{"verdict":"오답","why":"물리 계층은 전기적·기계적 특성을 이용해 비트를 전송 매체로 전달하는 계층이다."},{"verdict":"오답","why":"세션 계층은 응용 프로그램 간의 대화(세션)를 설정·유지·동기화하는 계층이다."},{"verdict":"오답","why":"응용 계층은 사용자가 네트워크에 접근할 수 있도록 서비스를 제공하는 최상위 계층이다."}],"keywords":[{"term":"OSI 7계층","desc":"물리, 데이터 링크, 네트워크, 전송, 세션, 표현, 응용"},{"term":"데이터 링크 계층","desc":"인접 노드 간 프레임 전송, 오류·흐름 제어, 프로토콜 HDLC·PPP 등"},{"term":"네트워크 계층","desc":"경로 설정(라우팅)과 패킷 전달, 프로토콜 IP 등"}],"memo":"'노드 간'이면 데이터 링크(2계층), '종단 간(End-to-End)'이면 전송(4계층)."}},{"id":"written-2020-3-72","no":72,"unit":"프로그래밍 언어 활용","q":"다음 중 가장 결합도가 강한 것은?","choices":["data coupling","stamp coupling","common coupling","control coupling"],"ans":3,"rate":57,"wiki":[{"title":"결합도","url":"https://itwiki.kr/w/결합도"}],"exp":{"concept":"결합도는 모듈 사이의 의존 정도이며, 약할수록 좋은 설계다. 약한 것부터 자료(data) < 스탬프(stamp) < 제어(control) < 외부(external) < 공통(common) < 내용(content) 결합도 순서다. 보기 중에서는 전역 변수를 함께 쓰는 공통 결합도가 가장 강하다.","choices":[{"verdict":"오답","why":"자료 결합도는 모듈 간에 필요한 데이터만 매개변수로 주고받는 가장 약한 결합도다."},{"verdict":"오답","why":"스탬프 결합도는 배열이나 레코드 같은 자료 구조를 주고받는 경우로, 자료 결합도 다음으로 약하다."},{"verdict":"정답","why":"공통 결합도는 여러 모듈이 공유하는 전역 변수를 참조하고 갱신하는 경우로, 보기 중 가장 강하다."},{"verdict":"오답","why":"제어 결합도는 다른 모듈의 처리 흐름을 제어하는 신호(플래그 등)를 넘기는 경우로, 공통 결합도보다 약하다."}],"keywords":[{"term":"결합도 순서(약→강)","desc":"자료 < 스탬프 < 제어 < 외부 < 공통 < 내용"},{"term":"공통 결합도","desc":"공유 전역 변수를 여러 모듈이 사용"},{"term":"내용 결합도","desc":"한 모듈이 다른 모듈의 내부 기능·자료를 직접 참조, 가장 강함"}],"memo":"결합도는 '자스제외공내' 순서로 강해진다."}},{"id":"written-2020-3-73","no":73,"unit":"프로그래밍 언어 활용","q":"메모리 관리 기법 중 Worst fit 방법을 사용할 경우 10K 크기의 프로그램 실행을 위해서는 어느 부분에 할당되는가?\n<img src=\"data/img/eip_written_20200822_073.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["NO.2","NO.3","NO.4","NO.5"],"ans":4,"rate":60,"wiki":[{"title":"메모리 할당","url":"https://itwiki.kr/w/메모리 할당"}],"exp":{"concept":"최악 적합(Worst fit)은 프로그램을 넣을 수 있는 빈 공간 중 가장 큰 곳에 배치하는 방법이다. 10K가 들어갈 수 있는 FREE 영역은 NO.2(12K)와 NO.5(16K)이고, NO.1(8K)은 너무 작으며 NO.3, NO.4는 사용 중이다. 둘 중 가장 큰 NO.5에 할당된다.","choices":[{"verdict":"오답","why":"NO.2(12K)는 10K가 들어가는 가장 작은 공간이므로 최적 적합(Best fit)에서 선택되며, 최초 적합(First fit)에서도 첫 번째로 들어갈 수 있는 곳이라 선택된다."},{"verdict":"오답","why":"NO.3은 IN USE 상태라 할당할 수 없다."},{"verdict":"오답","why":"NO.4는 20K로 가장 크지만 IN USE 상태라 할당할 수 없다."},{"verdict":"정답","why":"10K를 넣을 수 있는 빈 공간 NO.2(12K), NO.5(16K) 중 가장 큰 NO.5에 할당된다."}],"keywords":[{"term":"최초 적합","desc":"First fit, 들어갈 수 있는 첫 번째 빈 공간에 배치"},{"term":"최적 적합","desc":"Best fit, 들어갈 수 있는 가장 작은 빈 공간에 배치, 단편화 최소"},{"term":"최악 적합","desc":"Worst fit, 들어갈 수 있는 가장 큰 빈 공간에 배치"}],"memo":"사용 중(IN USE)인 영역을 먼저 지우고 나서 크기를 비교해야 NO.4 함정에 걸리지 않는다."}},{"id":"written-2020-3-74","no":74,"unit":"프로그래밍 언어 활용","q":"200.1.1.0/24 네트워크를 FLSM 방식을 이용하여 10개의 Subnet으로 나누고 ip subnet-zero를 적용했다. 이때 서브네팅된 네트워크 중 10번째 네트워크의 broadcast IP주소는?","choices":["200.1.1.159","201.1.5.175","202.1.11.254","203.1.255.245"],"ans":1,"rate":56,"wiki":[{"title":"서브넷","url":"https://itwiki.kr/w/서브넷"}],"exp":{"concept":"FLSM(고정 길이 서브넷 마스크)은 네트워크를 같은 크기로 나눈다. 10개로 나누려면 2의 4제곱 = 16 ≥ 10이므로 호스트 부분에서 4비트를 빌려 /28이 되고, 서브넷 하나는 2의 4제곱 = 16개 주소를 가진다. subnet-zero를 적용하면 첫 번째 서브넷이 200.1.1.0이므로 10번째 서브넷은 9 × 16 = 144에서 시작하는 200.1.1.144/28 이고, 브로드캐스트 주소는 그 마지막 주소 144 + 15 = 159, 즉 200.1.1.159다.","choices":[{"verdict":"정답","why":"10번째 서브넷 200.1.1.144/28의 범위는 144~159이므로 브로드캐스트 주소는 200.1.1.159다."},{"verdict":"오답","why":"200.1.1.0/24를 나눈 서브넷은 모두 200.1.1.x 형태여야 하는데 201.1.5.175는 네트워크 부분부터 다르다."},{"verdict":"오답","why":"202.1.11.254는 200.1.1.0/24 범위 밖의 주소다."},{"verdict":"오답","why":"203.1.255.245는 200.1.1.0/24 범위 밖의 주소다."}],"keywords":[{"term":"FLSM","desc":"Fixed Length Subnet Mask, 모든 서브넷을 같은 크기로 분할"},{"term":"ip subnet-zero","desc":"첫 번째(0번) 서브넷도 사용 가능하게 하는 설정"},{"term":"브로드캐스트 주소","desc":"서브넷의 마지막 주소, 해당 서브넷 전체에 전송"}],"memo":"n번째 서브넷 시작 = (n - 1) × 블록 크기, 브로드캐스트 = 다음 서브넷 시작 - 1."}},{"id":"written-2020-3-75","no":75,"unit":"프로그래밍 언어 활용","q":"다음은 사용자로부터 입력받은 문자열에서 처음과 끝의 3글자를 추출한 후 합쳐서 출력하는 파이썬 코드에서 ㉠에 들어갈 내용은?\n<img src=\"data/img/eip_written_20200822_075.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["string[1:3] + string[-3:]","string[:3] + string[-3:-1]","string[0:3] + string[-3:]","string[0:] + string[:-1]"],"ans":3,"rate":74,"exp":{"concept":"파이썬 슬라이싱 string[시작:끝]은 시작 위치부터 끝 위치 바로 앞까지 잘라 낸다. 인덱스는 0부터 시작하고, 음수 인덱스는 뒤에서부터 센다(-1이 마지막 글자). 'Hello World'에서 처음 3글자는 string[0:3] = 'Hel', 마지막 3글자는 string[-3:] = 'rld'이므로 둘을 더하면 'Helrld'가 된다.","choices":[{"verdict":"오답","why":"string[1:3]은 인덱스 1, 2의 'el'만 잘라 'elrld'가 출력된다."},{"verdict":"오답","why":"string[-3:-1]은 끝 인덱스 -1 바로 앞까지라 'rl'만 잘려 'Helrl'이 출력된다."},{"verdict":"정답","why":"string[0:3]은 'Hel', string[-3:]은 'rld'이므로 'Helrld'가 출력된다."},{"verdict":"오답","why":"string[0:]은 문자열 전체, string[:-1]은 마지막 글자를 뺀 전체라 'Hello WorldHello Worl'이 출력된다."}],"keywords":[{"term":"슬라이싱","desc":"s[시작:끝:간격], 끝 인덱스는 포함하지 않음"},{"term":"음수 인덱스","desc":"-1은 마지막 글자, -3은 뒤에서 세 번째 글자"},{"term":"생략","desc":"s[:3]은 처음부터, s[-3:]은 끝까지"}],"memo":"슬라이싱의 끝 번호는 '포함하지 않는다'. 끝까지 가려면 끝 번호를 비워 둔다."}},{"id":"written-2020-3-76","no":76,"unit":"프로그래밍 언어 활용","q":"파이썬의 변수 작성 규칙 설명으로 옳지 않은 것은?","choices":["첫 자리에 숫자를 사용할 수 없다.","영문 대문자/소문자, 숫자, 밑줄(_)의 사용이 가능하다.","변수 이름의 중간에 공백을 사용할 수 있다.","이미 사용되고 있는 예약어는 사용할 수 없다."],"ans":3,"rate":82,"exp":{"concept":"파이썬 변수 이름은 영문 대소문자, 숫자, 밑줄(_)로 만들 수 있다. 첫 글자로 숫자는 올 수 없고, if·for 같은 예약어는 쓸 수 없으며, 이름 중간에 공백을 넣을 수 없다. 대문자와 소문자는 다른 이름으로 구별한다.","choices":[{"verdict":"오답","why":"변수 이름의 첫 자리에 숫자를 쓸 수 없다는 것은 맞는 규칙이다."},{"verdict":"오답","why":"영문 대소문자, 숫자, 밑줄(_)을 사용할 수 있다는 것은 맞는 규칙이다."},{"verdict":"정답","why":"변수 이름에는 공백을 넣을 수 없다. 단어를 이으려면 my_name처럼 밑줄을 쓴다."},{"verdict":"오답","why":"예약어(키워드)는 변수 이름으로 쓸 수 없다는 것은 맞는 규칙이다."}],"keywords":[{"term":"식별자 규칙","desc":"영문자·숫자·밑줄 사용, 숫자로 시작 불가, 공백 불가, 예약어 불가"},{"term":"대소문자 구분","desc":"파이썬은 Name과 name을 서로 다른 변수로 취급"}],"memo":"공백이 있으면 파이썬은 두 개의 이름으로 읽는다. 변수 이름에 공백은 절대 불가."}},{"id":"written-2020-3-77","no":77,"unit":"프로그래밍 언어 활용","q":"어떤 모듈이 다른 모듈의 내부 논리 조직을 제어하기 위한 목적으로 제어신호를 이용하여 통신하는 경우이며, 하위 모듈에서 상위 모듈로 제어신호가 이동하여 상위 모듈에게 처리 명령을 부여하는 권리 전도현상이 발생하게 되는 결합도는?","choices":["data coupling","stamp coupling","control coupling","common coupling"],"ans":3,"rate":74,"wiki":[{"title":"결합도","url":"https://itwiki.kr/w/결합도"}],"exp":{"concept":"제어 결합도(Control Coupling)는 한 모듈이 다른 모듈의 처리 흐름을 바꾸려고 제어 신호(플래그 등)를 넘겨주는 경우다. 하위 모듈이 상위 모듈에 제어 신호를 보내 처리를 지시하면, 지시하는 쪽과 받는 쪽이 뒤바뀌는 권리 전도 현상이 생긴다.","choices":[{"verdict":"오답","why":"자료 결합도는 필요한 데이터만 매개변수로 주고받는 경우로, 제어 신호를 넘기지 않는다."},{"verdict":"오답","why":"스탬프 결합도는 배열이나 레코드 같은 자료 구조를 주고받는 경우다."},{"verdict":"정답","why":"제어 신호로 다른 모듈의 내부 논리를 제어하고 권리 전도 현상이 생기는 것은 제어 결합도다."},{"verdict":"오답","why":"공통 결합도는 여러 모듈이 공유 전역 변수를 함께 사용하는 경우다."}],"keywords":[{"term":"제어 결합도","desc":"제어 신호(플래그)로 다른 모듈의 논리 흐름을 제어, 권리 전도 발생"},{"term":"외부 결합도","desc":"어떤 모듈에서 선언한 데이터(변수)를 외부의 다른 모듈에서 참조"}],"memo":"'제어 신호', '권리 전도'라는 말이 보이면 제어 결합도."}},{"id":"written-2020-3-78","no":78,"unit":"프로그래밍 언어 활용","q":"다음 C 프로그램의 결과 값은?\n<img src=\"data/img/eip_written_20200822_078.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["15","19","25","27"],"ans":3,"rate":82,"exp":{"concept":"for(i = 1; i <= 10; i = i + 2)는 i가 1부터 2씩 늘어나며 10 이하인 동안 반복하므로 i = 1, 3, 5, 7, 9에서 실행된다. sum에 차례로 더하면 1 → 4 → 9 → 16 → 25가 된다. i가 11이 되면 조건이 거짓이라 반복을 끝내고 25를 출력한다.","choices":[{"verdict":"오답","why":"15는 1부터 5까지의 합(1+2+3+4+5)으로, 이 반복문의 결과가 아니다."},{"verdict":"오답","why":"19는 이 반복문의 어느 단계에서도 sum 값으로 나오지 않는다. 각 단계 값은 1, 4, 9, 16, 25다."},{"verdict":"정답","why":"1부터 9까지의 홀수 1, 3, 5, 7, 9를 더하므로 sum = 25가 출력된다."},{"verdict":"오답","why":"27은 sum이 거치는 값(1, 4, 9, 16, 25) 중 어디에도 없다. 반복은 i가 11이 되어 i <= 10이 거짓일 때 끝나므로 결과는 25다."}],"keywords":[{"term":"for문","desc":"for(초기식; 조건식; 증감식), 조건이 참인 동안 반복"},{"term":"누적 합","desc":"sum = sum + i로 반복마다 값을 더해 감"}],"memo":"1부터 연속된 홀수 n개의 합은 n의 제곱이다. 홀수 5개이므로 25."}},{"id":"written-2020-3-79","no":79,"unit":"프로그래밍 언어 활용","q":"UNIX에서 새로운 프로세스를 생성하는 명령어는?","choices":["ls","cat","fork","chmod"],"ans":3,"rate":65,"exp":{"concept":"UNIX에서 fork는 현재 실행 중인 프로세스를 복제해 새로운 자식 프로세스를 만드는 시스템 호출(명령)이다. 새로 생긴 자식 프로세스는 부모와 같은 코드를 이어서 실행한다.","choices":[{"verdict":"오답","why":"ls는 디렉터리 안의 파일 목록을 보여 주는 명령어다."},{"verdict":"오답","why":"cat은 파일 내용을 화면에 출력하거나 파일을 이어 붙이는 명령어다."},{"verdict":"정답","why":"fork는 기존 프로세스를 복제해 새 프로세스를 생성한다."},{"verdict":"오답","why":"chmod는 파일이나 디렉터리의 접근 권한을 변경하는 명령어다."}],"keywords":[{"term":"fork","desc":"프로세스를 복제해 새 자식 프로세스 생성"},{"term":"exec","desc":"현재 프로세스를 새로운 프로그램으로 교체해 실행"},{"term":"chmod","desc":"파일 접근 권한(읽기·쓰기·실행) 변경"}],"memo":"fork는 '포크처럼 갈라진다' → 프로세스가 둘로 갈라져 새로 생긴다."}},{"id":"written-2020-3-80","no":80,"unit":"프로그래밍 언어 활용","q":"C언어에서 정수 자료형으로 옳은 것은?","choices":["int","float","char","double"],"ans":1,"rate":89,"exp":{"concept":"C언어의 기본 자료형은 정수형, 실수형, 문자형으로 나눌 수 있다. 정수형의 대표는 int(보통 4바이트)이고 short, long도 정수형이다. float와 double은 소수점을 표현하는 실수형, char는 문자 하나를 저장하는 문자형이다.","choices":[{"verdict":"정답","why":"int는 정수를 저장하는 C언어의 대표 정수 자료형이다."},{"verdict":"오답","why":"float는 단정도 실수형으로 보통 4바이트에 소수점이 있는 수를 저장한다."},{"verdict":"오답","why":"char는 문자 하나를 저장하는 문자형(1바이트)이다. 내부적으로는 문자 코드를 정수로 저장한다."},{"verdict":"오답","why":"double은 배정도 실수형으로 보통 8바이트에 float보다 정밀한 실수를 저장한다."}],"keywords":[{"term":"정수형","desc":"short, int, long, long long"},{"term":"실수형","desc":"float(4바이트), double(8바이트)"},{"term":"문자형","desc":"char(1바이트)"}],"memo":"int는 integer(정수)의 줄임말이다.","doubt":"C 표준은 char도 정수 계열 자료형(integer type)으로 분류하므로 3번도 엄밀히는 정수 자료형이라 볼 여지가 있다. 시험에서는 문자형으로 구분하므로 정답은 1번 int다."}},{"id":"written-2020-3-81","no":81,"unit":"정보시스템 구축 관리","q":"물리적인 사물과 컴퓨터에 동일하게 표현되는 가상의 모델로 실제 물리적인 자산 대신 소프트웨어로 가상화함으로써 실제 자산의 특성에 대한 정확한 정보를 얻을 수 있고, 자산 최적화, 돌발사고 최소화, 생산성 증가 등 설계부터 제조, 서비스에 이르는 모든 과정의 효율성을 향상시킬 수 있는 모델은?","choices":["최적화","실행 시간","디지털 트윈","N-Screen"],"ans":3,"rate":66,"wiki":[{"title":"디지털 트윈","url":"https://itwiki.kr/w/디지털 트윈"}],"exp":{"concept":"디지털 트윈(Digital Twin)은 현실의 사물이나 공장, 도시를 컴퓨터 속에 쌍둥이처럼 똑같이 만든 가상 모델이다. 가상 모델로 미리 시험하고 분석해 실제 자산의 상태를 정확히 파악하고, 고장을 예측하며, 생산성을 높인다.","choices":[{"verdict":"오답","why":"최적화는 주어진 조건에서 가장 좋은 결과를 찾는 일반적인 말로, 가상 쌍둥이 모델을 뜻하지 않는다."},{"verdict":"오답","why":"실행 시간은 프로그램이 실행되는 시간 또는 시점(런타임)을 뜻한다."},{"verdict":"정답","why":"물리적 사물을 컴퓨터에 똑같이 표현한 가상 모델로 효율성을 높이는 기술은 디지털 트윈이다."},{"verdict":"오답","why":"N-Screen은 하나의 콘텐츠를 스마트폰, PC, TV 등 여러 기기에서 끊김 없이 이어 보는 서비스다."}],"keywords":[{"term":"디지털 트윈","desc":"현실 사물을 가상 공간에 동일하게 구현한 모델"},{"term":"N-Screen","desc":"하나의 콘텐츠를 여러 단말기에서 이어서 이용하는 서비스"}],"memo":"트윈(Twin) = 쌍둥이. 현실과 똑같은 가상의 쌍둥이."}},{"id":"written-2020-3-82","no":82,"unit":"정보시스템 구축 관리","q":"정보보안의 3대 요소에 해당하지 않는 것은?","choices":["기밀성","휘발성","무결성","가용성"],"ans":2,"rate":86,"wiki":[{"title":"CIA","url":"https://itwiki.kr/w/CIA"}],"exp":{"concept":"정보보안의 3대 요소는 기밀성, 무결성, 가용성이다. 기밀성은 허가된 사람만 볼 수 있게, 무결성은 허가된 사람만 바꿀 수 있게, 가용성은 허가된 사람이 필요할 때 언제든 쓸 수 있게 하는 것이다.","choices":[{"verdict":"오답","why":"기밀성(Confidentiality)은 인가된 사용자만 정보에 접근하게 하는 3대 요소다."},{"verdict":"정답","why":"휘발성은 전원이 꺼지면 내용이 사라지는 메모리의 성질로, 정보보안 3대 요소가 아니다."},{"verdict":"오답","why":"무결성(Integrity)은 인가된 사용자만 정보를 수정할 수 있게 하는 3대 요소다."},{"verdict":"오답","why":"가용성(Availability)은 인가된 사용자가 필요할 때 정보를 사용할 수 있게 하는 3대 요소다."}],"keywords":[{"term":"CIA","desc":"기밀성(Confidentiality), 무결성(Integrity), 가용성(Availability)"},{"term":"그 밖의 보안 요소","desc":"인증(Authentication), 부인 방지(Non-repudiation)"}],"memo":"정보보안 3요소는 CIA(기무가)로 외운다."}},{"id":"written-2020-3-83","no":83,"unit":"정보시스템 구축 관리","q":"다음 빈칸에 알맞은 기술은\n<img src=\"data/img/eip_written_20200822_083.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Quantum Key Distribution","Digital Rights Management","Grayware","Mashup"],"ans":4,"rate":64,"exp":{"concept":"매시업(Mashup)은 웹에서 공개된 여러 정보와 서비스(지도, 날씨, 검색 API 등)를 섞어 새로운 소프트웨어나 서비스를 만드는 기술이다. 지도 API에 맛집 정보를 얹어 맛집 지도를 만드는 것이 대표적인 예다.","choices":[{"verdict":"오답","why":"Quantum Key Distribution(양자 키 분배)은 양자 통신의 원리를 이용해 암호 키를 안전하게 나누어 갖는 기술이다."},{"verdict":"오답","why":"Digital Rights Management(DRM)는 디지털 콘텐츠의 저작권을 보호하고 사용을 통제하는 기술이다."},{"verdict":"오답","why":"Grayware(그레이웨어)는 악성 코드는 아니지만 사용자에게 불편을 줄 수 있는 애드웨어·스파이웨어 같은 프로그램이다."},{"verdict":"정답","why":"웹에서 제공하는 정보와 서비스를 이용해 새로운 소프트웨어·서비스·데이터베이스를 만드는 기술은 Mashup이다."}],"keywords":[{"term":"Mashup","desc":"웹의 여러 정보·서비스를 조합해 새 서비스를 만드는 기술"},{"term":"Open API","desc":"누구나 사용할 수 있도록 공개된 API, 매시업의 재료"}],"memo":"Mash = 으깨어 섞다. 여러 웹 서비스를 섞어 새것을 만든다."}},{"id":"written-2020-3-84","no":84,"unit":"정보시스템 구축 관리","q":"기능점수(Functional Point)모형에서 비용산정에 이용되는 요소가 아닌 것은?","choices":["클래스 인터페이스","명령어(사용자 질의수)","데이터파일","출력보고서"],"ans":1,"rate":46,"wiki":[{"title":"기능 점수","url":"https://itwiki.kr/w/기능 점수"}],"exp":{"concept":"기능 점수(FP, Function Point) 모형은 소프트웨어가 제공하는 기능의 수와 복잡도를 점수로 매겨 비용을 산정하는 방법이다. 산정 요소는 자료 입력(입력 양식), 정보 출력(출력 보고서), 명령어(사용자 질의 수), 데이터 파일, 외부 루틴과의 인터페이스다.","choices":[{"verdict":"정답","why":"클래스 인터페이스는 기능 점수 모형의 비용 산정 요소가 아니다. FP의 인터페이스 요소는 외부 루틴(시스템)과의 인터페이스다."},{"verdict":"오답","why":"명령어(사용자 질의 수)는 기능 점수 산정 요소다."},{"verdict":"오답","why":"데이터 파일은 기능 점수 산정 요소다."},{"verdict":"오답","why":"출력 보고서는 기능 점수 산정 요소다."}],"keywords":[{"term":"기능 점수(FP)","desc":"기능별 가중치로 점수를 매겨 규모·비용을 산정하는 모형"},{"term":"FP 산정 요소","desc":"입력 양식, 출력 보고서, 사용자 질의 수, 데이터 파일, 외부 인터페이스"},{"term":"FP 자동화 도구","desc":"ESTIMACS"}],"memo":"FP는 '사용자 눈에 보이는 기능'을 센다. 클래스 같은 내부 설계 요소는 세지 않는다."}},{"id":"written-2020-3-85","no":85,"unit":"정보시스템 구축 관리","q":"블록 암호화 방식이 아닌 것은?","choices":["DES","RC4","AES","SEED"],"ans":2,"rate":60,"wiki":[{"title":"블록 암호","url":"https://itwiki.kr/w/블록 암호"}],"exp":{"concept":"대칭키 암호는 데이터를 일정한 크기의 블록으로 잘라 암호화하는 블록 암호와, 비트·바이트 단위로 차례차례 암호화하는 스트림 암호로 나뉜다. DES, AES, SEED는 블록 암호이고, RC4는 스트림 암호다.","choices":[{"verdict":"오답","why":"DES는 64비트 블록 단위로 암호화하는 블록 암호다."},{"verdict":"정답","why":"RC4는 바이트 단위로 연속해서 암호화하는 스트림 암호이므로 블록 암호가 아니다."},{"verdict":"오답","why":"AES는 128비트 블록 단위로 암호화하는 블록 암호로, DES의 뒤를 이은 미국 표준이다."},{"verdict":"오답","why":"SEED는 한국인터넷진흥원(KISA)이 개발한 128비트 블록 암호다."}],"keywords":[{"term":"블록 암호","desc":"DES, AES, SEED, ARIA, IDEA, Skipjack 등"},{"term":"스트림 암호","desc":"RC4, LFSR 등"}],"memo":"자주 나오는 스트림 암호는 RC4 하나만 외워 두면, 블록 암호 보기들 사이에 섞인 RC4를 바로 골라낼 수 있다."}},{"id":"written-2020-3-86","no":86,"unit":"정보시스템 구축 관리","q":"Putnam 모형을 기초로 해서 만든 자동화 추정 도구는?","choices":["SQLR/30","SLIM","MESH","NFV"],"ans":2,"rate":64,"exp":{"concept":"Putnam 모형은 소프트웨어 생명주기 전체에 걸쳐 노력이 어떻게 분포하는지를 Rayleigh-Norden 곡선으로 가정해 비용을 추정하는 모형이다. 이 모형을 기초로 만든 자동화 추정 도구가 SLIM이다.","choices":[{"verdict":"오답","why":"SQLR/30은 Putnam 모형 기반 도구가 아니며 출제 범위의 표준 비용 추정 도구가 아니다."},{"verdict":"정답","why":"SLIM은 Rayleigh-Norden 곡선과 Putnam 예측 모델을 기초로 개발된 자동화 추정 도구다."},{"verdict":"오답","why":"MESH는 Putnam 모형 기반 추정 도구가 아니며 출제 범위의 표준 비용 추정 도구가 아니다."},{"verdict":"오답","why":"NFV(Network Functions Virtualization)는 네트워크 장비의 기능을 소프트웨어로 가상화하는 네트워크 기술이다."}],"keywords":[{"term":"Putnam 모형","desc":"Rayleigh-Norden 곡선 기반의 생명주기 비용 예측 모형"},{"term":"SLIM","desc":"Putnam 모형 기반 자동화 비용 추정 도구"},{"term":"ESTIMACS","desc":"기능 점수(FP) 모형 기반 자동화 추정 도구"}],"memo":"Putnam은 SLIM, FP는 ESTIMACS로 짝지어 외운다."}},{"id":"written-2020-3-87","no":87,"unit":"정보시스템 구축 관리","q":"큰 숫자를 소인수 분해하기 어렵다는 기반 하에 1978년 MIT에 의해 제안된 공개키 암호화 알고리즘은?","choices":["DES","ARIA","SEED","RSA"],"ans":4,"rate":71,"wiki":[{"title":"RSA","url":"https://itwiki.kr/w/RSA"}],"exp":{"concept":"RSA는 1978년 MIT의 리베스트(Rivest), 샤미르(Shamir), 애들먼(Adleman)이 제안한 공개키 암호 알고리즘으로, 이름도 세 사람 성의 첫 글자다. 큰 두 소수를 곱하기는 쉽지만 그 곱을 다시 소인수분해하기는 매우 어렵다는 점을 안전성의 근거로 한다.","choices":[{"verdict":"오답","why":"DES는 미국 표준으로 쓰인 대칭키(비밀키) 블록 암호로, 공개키 암호가 아니다."},{"verdict":"오답","why":"ARIA는 한국에서 개발한 128비트 대칭키 블록 암호다."},{"verdict":"오답","why":"SEED는 한국인터넷진흥원(KISA)이 개발한 128비트 대칭키 블록 암호다."},{"verdict":"정답","why":"큰 수의 소인수분해가 어렵다는 점에 기반해 1978년 MIT에서 제안된 공개키 암호는 RSA다."}],"keywords":[{"term":"RSA","desc":"소인수분해의 어려움에 기반한 공개키 암호, 1978년 MIT"},{"term":"공개키 암호","desc":"RSA, ECC, ElGamal, Diffie-Hellman 등, 암호화 키와 복호화 키가 다름"},{"term":"ECC","desc":"타원 곡선 이산대수 문제에 기반한 공개키 암호"}],"memo":"소인수분해 = RSA, 이산대수 = ElGamal·Diffie-Hellman, 타원 곡선 = ECC."}},{"id":"written-2020-3-88","no":88,"unit":"정보시스템 구축 관리","q":"COCOMO 모델의 프로젝트 유형으로 거리가 먼 것은?","choices":["Organic","Semi-detached","Embedded","Sequential"],"ans":4,"rate":70,"wiki":[{"title":"COCOMO","url":"https://itwiki.kr/w/COCOMO"}],"exp":{"concept":"COCOMO는 보헴(Boehm)이 제안한 비용 추정 모형으로, 프로그램 규모(LOC)를 바탕으로 비용을 계산한다. 프로젝트 유형은 조직형(Organic), 반분리형(Semi-detached), 내장형(Embedded) 세 가지이며 뒤로 갈수록 복잡하고 규모가 크다.","choices":[{"verdict":"오답","why":"조직형(Organic)은 기관 내부에서 개발하는 중소 규모(5만 라인 이하) 소프트웨어 유형이다."},{"verdict":"오답","why":"반분리형(Semi-detached)은 조직형과 내장형의 중간 형태(30만 라인 이하) 유형이다."},{"verdict":"오답","why":"내장형(Embedded)은 하드웨어와 밀접한 초대형 규모(30만 라인 이상) 유형이다."},{"verdict":"정답","why":"Sequential은 COCOMO의 프로젝트 유형에 포함되지 않는다."}],"keywords":[{"term":"COCOMO 유형","desc":"조직형(Organic), 반분리형(Semi-detached), 내장형(Embedded)"},{"term":"COCOMO 모델 종류","desc":"기본형(Basic), 중간형(Intermediate), 발전형(Detailed)"}],"memo":"COCOMO 유형은 '조반내'로 외운다."}},{"id":"written-2020-3-89","no":89,"unit":"정보시스템 구축 관리","q":"빅데이터 분석 기술 중 대량의 데이터를 분석하여 데이터 속에 내재되어 있는 변수 사이의 상호관례를 규명하여 일정한 패턴을 찾아내는 기법은?","choices":["Data Mining","Wm-Bus","Digital Twin","Zigbee"],"ans":1,"rate":79,"wiki":[{"title":"데이터 마이닝","url":"https://itwiki.kr/w/데이터 마이닝"}],"exp":{"concept":"데이터 마이닝(Data Mining)은 광산에서 광물을 캐내듯 대량의 데이터 속에서 변수 사이의 관계나 숨은 패턴을 찾아내는 분석 기법이다. 마트 판매 기록에서 '기저귀를 사는 사람은 맥주도 산다' 같은 규칙을 찾는 것이 예다.","choices":[{"verdict":"정답","why":"대량의 데이터에서 변수 간 상호관계를 규명해 패턴을 찾아내는 기법은 데이터 마이닝이다."},{"verdict":"오답","why":"Wm-Bus(Wireless M-Bus)는 가스·수도·전기 계량기의 원격 검침을 위한 무선 통신 규격이다."},{"verdict":"오답","why":"Digital Twin은 현실 사물을 가상 공간에 똑같이 구현한 모델이다."},{"verdict":"오답","why":"Zigbee는 저전력·저속의 근거리 무선 통신 기술로 센서 네트워크 등에 쓰인다."}],"keywords":[{"term":"데이터 마이닝","desc":"대량의 데이터에서 숨은 규칙과 패턴을 찾는 기법"},{"term":"데이터 마이닝 기법","desc":"연관 규칙, 분류, 군집화(클러스터링), 순차 패턴 등"}],"memo":"Mining = 채굴. 데이터 더미에서 패턴을 캐낸다."}},{"id":"written-2020-3-90","no":90,"unit":"정보시스템 구축 관리","q":"기존 무선 랜의 한계 극복을 위해 등장하였으며, 대규모 디바이스의 네트워크 생성에 최적화되어 차세대 이동통신, 홈네트워킹, 공공 안전 등의 특수목적을 위한 새로운 방식의 네트워크 기술을 의미하는 것은?","choices":["Software Defined Perimeter","Virtual Private Network","Local Area Network","Mesh Network"],"ans":4,"rate":60,"exp":{"concept":"메시 네트워크(Mesh Network)는 여러 기기(노드)가 그물처럼 서로 직접 연결되어 데이터를 주고받는 네트워크다. 기존 무선 랜의 한계를 극복하고 대규모 디바이스 네트워크를 만들기에 알맞아, 차세대 이동통신, 홈 네트워킹, 공공 안전 같은 특수 목적에 쓰인다.","choices":[{"verdict":"오답","why":"SDP(Software Defined Perimeter)는 인증된 사용자와 기기에만 네트워크 접근을 허용해 내부 자원을 숨기는 보안 기술이다."},{"verdict":"오답","why":"VPN(Virtual Private Network)은 공중망 위에 암호화된 터널을 만들어 사설망처럼 쓰는 기술이다."},{"verdict":"오답","why":"LAN(Local Area Network)은 건물이나 학교처럼 좁은 지역을 연결하는 근거리 통신망이다."},{"verdict":"정답","why":"무선 랜의 한계를 극복하고 대규모 디바이스 네트워크 생성에 최적화된 특수 목적 네트워크 기술은 메시 네트워크다."}],"keywords":[{"term":"메시 네트워크","desc":"노드들이 그물형으로 연결된 대규모 디바이스용 네트워크"},{"term":"SDP","desc":"Software Defined Perimeter, 인증 후에만 연결을 허용하는 보안 경계 기술"}],"memo":"Mesh = 그물. '대규모 디바이스', '무선 랜 한계 극복'이 보이면 메시 네트워크."}},{"id":"written-2020-3-91","no":91,"unit":"정보시스템 구축 관리","q":"DDoS 공격과 연관이 있는 공격 방법은?","choices":["Secure shell","Tribe Flood Network","Nimda","Deadlock"],"ans":2,"rate":62,"exp":{"concept":"DDoS(분산 서비스 거부) 공격은 여러 대의 감염된 컴퓨터를 이용해 한 대상에 한꺼번에 트래픽을 보내 서비스를 마비시키는 공격이다. TFN(Tribe Flood Network)은 Trinoo, Stacheldraht 등과 함께 대표적인 DDoS 공격 도구다.","choices":[{"verdict":"오답","why":"SSH(Secure Shell)는 원격 접속 시 통신을 암호화하는 보안 프로토콜이다."},{"verdict":"정답","why":"TFN(Tribe Flood Network)은 여러 에이전트를 이용해 대상에 대량 트래픽을 보내는 DDoS 공격 도구다."},{"verdict":"오답","why":"님다(Nimda)는 2001년에 퍼진 웜 바이러스로, 이메일·웹 등 여러 경로로 전파되었다."},{"verdict":"오답","why":"교착 상태(Deadlock)는 둘 이상의 프로세스가 서로의 자원을 기다리며 멈추는 운영체제 현상이다."}],"keywords":[{"term":"DDoS 공격 도구","desc":"Trinoo, TFN, TFN2K, Stacheldraht"},{"term":"DoS 공격 유형","desc":"Ping of Death, SYN Flooding, Smurf, Land Attack, TearDrop 등"}],"memo":"이름에 Flood(홍수)가 들어가면 트래픽을 퍼붓는 공격이다."}},{"id":"written-2020-3-92","no":92,"unit":"정보시스템 구축 관리","q":"CPM 네트워크가 다음과 같을 때 임계경로의 소요기일은?\n<img src=\"data/img/eip_written_20200822_092.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["10일","12일","14일","16일"],"ans":3,"rate":70,"wiki":[{"title":"CPM","url":"https://itwiki.kr/w/CPM"},{"title":"임계경로","url":"https://itwiki.kr/w/임계경로"}],"exp":{"concept":"임계 경로(Critical Path)는 시작부터 완료까지 가는 여러 경로 중 소요 기간이 가장 긴 경로이며, 그 길이가 프로젝트의 최소 완료 기간이다. 그림의 경로는 위쪽 2 + 2 + 3 + 3 = 10일, 가운데 2 + 3 + 5 + 4 = 14일, 아래쪽 3 + 5 + 4 = 12일이다. 가장 긴 14일이 임계 경로의 소요 기일이다.","choices":[{"verdict":"오답","why":"10일은 가장 짧은 위쪽 경로(2+2+3+3)의 길이로, 임계 경로는 가장 긴 경로다."},{"verdict":"오답","why":"12일은 아래쪽 경로(3+5+4)의 길이로, 가장 긴 경로가 아니다."},{"verdict":"정답","why":"가운데 경로 2 + 3 + 5 + 4 = 14일이 가장 길어 임계 경로가 된다."},{"verdict":"오답","why":"16일이 되는 경로는 그림에 없다."}],"keywords":[{"term":"CPM","desc":"Critical Path Method, 작업 네트워크에서 임계 경로를 찾아 일정을 관리"},{"term":"임계 경로","desc":"가장 긴 경로, 여유 시간이 0인 작업들로 이루어짐"},{"term":"PERT","desc":"낙관치·기대치·비관치 세 가지 시간 추정으로 일정을 계획하는 기법"}],"memo":"임계 경로는 '가장 짧은'이 아니라 '가장 긴' 경로다. 모든 갈림길에서 경로를 빠짐없이 적어 더한다."}},{"id":"written-2020-3-93","no":93,"unit":"정보시스템 구축 관리","q":"RIP(Routing Information Protocol)에 대한 설명으로 틀린 것은?","choices":["거리 벡터 라우팅 프로토콜이라고도 한다.","소규모 네트워크 환경에 적합하다.","최대 홉 카운트를 115홉 이하로 한정하고 있다.","최단경로탐색에는 Bellman-Ford 알고리즘을 사용한다."],"ans":3,"rate":69,"wiki":[{"title":"라우팅_프로토콜","url":"https://itwiki.kr/w/라우팅_프로토콜"}],"exp":{"concept":"RIP(Routing Information Protocol)는 목적지까지 거치는 라우터 수(홉 수)로 최단 경로를 정하는 거리 벡터 라우팅 프로토콜이다. 벨만-포드(Bellman-Ford) 알고리즘을 쓰며, 최대 홉 수를 15로 제한하므로 소규모 네트워크에 적합하다. 16홉은 도달 불가로 본다.","choices":[{"verdict":"오답","why":"RIP는 대표적인 거리 벡터(Distance Vector) 라우팅 프로토콜이다."},{"verdict":"오답","why":"최대 홉 수가 15로 제한되어 소규모 네트워크에 적합하다."},{"verdict":"정답","why":"RIP의 최대 홉 카운트는 15홉이므로 115홉이라는 설명은 틀렸다."},{"verdict":"오답","why":"RIP는 최단 경로 탐색에 벨만-포드 알고리즘을 사용한다."}],"keywords":[{"term":"RIP","desc":"거리 벡터, 벨만-포드, 최대 15홉, 소규모 네트워크"},{"term":"OSPF","desc":"링크 상태 라우팅, 다익스트라 알고리즘, 대규모 네트워크"}],"memo":"RIP 최대 15홉, 16이면 도달 불가. RIP는 벨만-포드, OSPF는 다익스트라."}},{"id":"written-2020-3-94","no":94,"unit":"정보시스템 구축 관리","q":"소프트웨어 생명주기 모형 중 고전적 생명주기 모형으로 선형 순차적 모델이라고도 하며, 타당성 검토, 계획, 요구사항 분석, 구현, 테스트, 유지보수의 단계를 통해 소프트웨어를 개발하는 모형은?","choices":["폭포수 모형","애자일 모형","컴포넌트 기반 방법론","6GT 모형"],"ans":1,"rate":88,"wiki":[{"title":"폭포수_모델","url":"https://itwiki.kr/w/폭포수_모델"}],"exp":{"concept":"폭포수 모형(Waterfall Model)은 개발 단계를 순서대로 하나씩 끝내고 다음 단계로 넘어가는 가장 오래된 생명주기 모형이다. 물이 위에서 아래로만 흐르듯 이전 단계로 돌아가기 어려워 고전적 생명주기 모형, 선형 순차적 모형이라고도 부른다.","choices":[{"verdict":"정답","why":"고전적 생명주기 모형이자 선형 순차적 모델로 단계를 차례로 진행하는 것은 폭포수 모형이다."},{"verdict":"오답","why":"애자일 모형은 짧은 주기로 반복 개발하며 변화에 유연하게 대응하는 방식이다."},{"verdict":"오답","why":"컴포넌트 기반 방법론(CBD)은 재사용 가능한 컴포넌트를 조립해 소프트웨어를 만드는 방법론이다."},{"verdict":"오답","why":"6GT 모형은 출제 범위의 표준 생명주기 모형이 아니다."}],"keywords":[{"term":"폭포수 모형","desc":"고전적, 선형 순차적 생명주기 모형, 단계별 산출물 명확"},{"term":"프로토타입 모형","desc":"견본(시제품)을 만들어 사용자 요구를 확인하며 개발"},{"term":"나선형 모형","desc":"계획·위험 분석·개발·평가를 반복하며 위험을 줄이는 모형"}],"memo":"'고전적', '선형 순차적'이라는 말이 나오면 폭포수 모형."}},{"id":"written-2020-3-95","no":95,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 모델 중 나선형 모델의 4가지 주요 활동이 순서대로 나열된 것은?\n<img src=\"data/img/eip_written_20200822_095.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Ⓐ-Ⓑ-Ⓓ-Ⓒ 순으로 반복","Ⓐ-Ⓓ-Ⓒ-Ⓑ 순으로 반복","Ⓐ-Ⓑ-Ⓒ-Ⓓ 순으로 반복","Ⓐ-Ⓒ-Ⓑ-Ⓓ 순으로 반복"],"ans":2,"rate":77,"wiki":[{"title":"나선형_모델","url":"https://itwiki.kr/w/나선형_모델"}],"exp":{"concept":"나선형 모형(Spiral Model)은 보헴이 제안한 모형으로, 같은 과정을 나선처럼 여러 번 반복하며 점점 완성도를 높인다. 한 바퀴마다 계획 수립 → 위험 분석 → 개발 및 검증 → 고객 평가 순서로 진행하며, 특히 위험 분석을 통해 위험을 줄이는 것이 핵심이다. 따라서 Ⓐ(계획 수립) → Ⓓ(위험 분석) → Ⓒ(개발 및 검증) → Ⓑ(고객 평가) 순서다.","choices":[{"verdict":"오답","why":"고객 평가(Ⓑ)는 개발이 끝난 뒤에 하는 마지막 활동이므로 계획 수립 바로 다음에 올 수 없다."},{"verdict":"정답","why":"계획 수립(Ⓐ) → 위험 분석(Ⓓ) → 개발 및 검증(Ⓒ) → 고객 평가(Ⓑ) 순서로 반복한다."},{"verdict":"오답","why":"위험 분석(Ⓓ)이 개발보다 먼저 와야 하고, 고객 평가(Ⓑ)는 개발 뒤에 와야 한다."},{"verdict":"오답","why":"개발 및 검증(Ⓒ) 전에 위험 분석(Ⓓ)을 먼저 해야 하므로 순서가 틀렸다."}],"keywords":[{"term":"나선형 모형","desc":"보헴 제안, 반복 개발과 위험 분석으로 위험을 최소화"},{"term":"나선형 4단계","desc":"계획 수립, 위험 분석, 개발 및 검증(공학적 개발), 고객 평가"}],"memo":"나선형은 '계위개고'(계획·위험·개발·고객 평가)로 외운다."}},{"id":"written-2020-3-96","no":96,"unit":"정보시스템 구축 관리","q":"전자 칩과 같은 소프트웨어 부품, 즉 블록(모듈)을 만들어서 끼워 맞추는 방법으로 소프트웨어를 완성시키는 재사용 방법은?","choices":["합성 중심","생성 중심","분리 중심","구조 중심"],"ans":1,"rate":70,"exp":{"concept":"소프트웨어 재사용 방법은 합성 중심과 생성 중심으로 나뉜다. 합성 중심(Composition-Based)은 전자 칩 같은 블록(모듈)을 만들어 끼워 맞추는 블록 구성 방법이고, 생성 중심(Generation-Based)은 추상화된 명세를 바탕으로 코드를 생성하는 패턴 구성 방법이다.","choices":[{"verdict":"정답","why":"모듈(블록)을 만들어 끼워 맞춰 소프트웨어를 완성하는 재사용 방법은 합성 중심이다."},{"verdict":"오답","why":"생성 중심은 추상화 형태로 쓰인 명세를 구체화해 프로그램을 만드는 패턴 구성 방법이다."},{"verdict":"오답","why":"분리 중심은 소프트웨어 재사용 방법의 분류가 아니다."},{"verdict":"오답","why":"구조 중심은 소프트웨어 재사용 방법의 분류가 아니다."}],"keywords":[{"term":"합성 중심","desc":"블록 구성 방법, 모듈을 끼워 맞춰 완성"},{"term":"생성 중심","desc":"패턴 구성 방법, 추상화된 명세로부터 생성"}],"memo":"블록을 '합쳐' 만들면 합성, 패턴으로 '생성'하면 생성 중심."}},{"id":"written-2020-3-97","no":97,"unit":"정보시스템 구축 관리","q":"다음 JAVA코드에서 밑줄로 표시된 부분에는 어떤 보안 약점이 존재하는가? (단, key는 암호화 키를 저장하는 변수이다.)\n<img src=\"data/img/eip_written_20200822_097.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["무결성 검사 없는 코드 다운로드","중요 자원에 대한 잘못된 권한 설정","하드코드된 암호화 키 사용","적절한 인증없는 중요 기능 허용"],"ans":3,"rate":77,"exp":{"concept":"밑줄 친 String key = \"22df3023sf~2;asn!@#/>as\";는 암호화 키를 소스 코드 안에 문자열로 직접 적어 넣은 것이다. 이렇게 하면 소스나 실행 파일을 본 사람 누구나 키를 알 수 있고, 키를 바꾸려면 코드를 다시 고쳐 배포해야 한다. 이를 하드코드된 암호화 키 사용이라는 보안 약점이라고 한다.","choices":[{"verdict":"오답","why":"무결성 검사 없는 코드 다운로드는 원격에서 받은 코드를 해시·서명 검사 없이 실행하는 약점이다."},{"verdict":"오답","why":"중요 자원에 대한 잘못된 권한 설정은 설정 파일 등 중요 자원에 누구나 접근할 수 있게 권한을 준 약점이다."},{"verdict":"정답","why":"암호화 키를 소스 코드 안에 상수 문자열로 직접 넣었으므로 하드코드된 암호화 키 사용이다."},{"verdict":"오답","why":"적절한 인증 없는 중요 기능 허용은 인증 절차 없이 중요한 기능을 실행하게 하는 약점이다."}],"keywords":[{"term":"하드코드된 암호화 키","desc":"암호화 키를 소스에 상수로 직접 기록해 노출 위험이 큰 약점"},{"term":"대응 방법","desc":"키를 암호화해 별도의 안전한 저장소나 설정 파일로 분리해 관리"}],"memo":"코드 안에 따옴표로 된 비밀번호·키가 보이면 '하드코드'다."}},{"id":"written-2020-3-98","no":98,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 표준 중 소프트웨어 품질 및 생산성 향상을 위해 소프트웨어 프로세스를 평가 및 개선하는 국제 표준은?","choices":["SCRUM","ISO/IEC 12509","SPICE","CASE"],"ans":3,"rate":57,"wiki":[{"title":"SPICE","url":"https://itwiki.kr/w/SPICE"}],"exp":{"concept":"SPICE(Software Process Improvement and Capability dEtermination)는 소프트웨어 프로세스를 평가하고 개선해 품질과 생산성을 높이기 위한 국제 표준(ISO/IEC 15504)이다. 프로세스 수행 능력을 0~5의 6단계로 평가한다.","choices":[{"verdict":"오답","why":"스크럼(SCRUM)은 스프린트 단위로 반복 개발하는 애자일 개발 방법론이지 프로세스 평가 국제 표준이 아니다."},{"verdict":"오답","why":"ISO/IEC 12509는 소프트웨어 프로세스 평가 표준이 아니며 출제 범위의 표준 번호가 아니다."},{"verdict":"정답","why":"소프트웨어 프로세스를 평가·개선하는 국제 표준은 SPICE(ISO/IEC 15504)다."},{"verdict":"오답","why":"CASE는 소프트웨어 개발 과정을 자동화하는 도구로, 국제 표준이 아니다."}],"keywords":[{"term":"SPICE","desc":"ISO/IEC 15504, 소프트웨어 프로세스 평가·개선 국제 표준"},{"term":"SPICE 수행 능력 단계","desc":"0 불완전, 1 수행, 2 관리, 3 확립, 4 예측, 5 최적화"},{"term":"CMMI","desc":"소프트웨어 개발 조직의 업무 능력과 성숙도를 평가하는 모델"}],"memo":"프로세스 '평가·개선' 국제 표준 = SPICE = 15504."}},{"id":"written-2020-3-99","no":99,"unit":"정보시스템 구축 관리","q":"실무적으로 검증된 개발보안 방법론 중 하나로써 SW보안의 모범 사례를 SDLC(Software Development Life Cycle)에 통합한 소프트웨어 개발 보안 생명주기 방법론은?","choices":["CLASP","CWE","PIMS","Seven Touchpoints"],"ans":4,"rate":48,"wiki":[{"title":"세븐 터치포인트","url":"https://itwiki.kr/w/세븐 터치포인트"},{"title":"CWE","url":"https://itwiki.kr/w/CWE"},{"title":"PIM","url":"https://itwiki.kr/w/PIM"},{"title":"CLASP","url":"https://itwiki.kr/w/CLASP"}],"exp":{"concept":"Seven Touchpoints는 실무적으로 검증된 개발 보안 방법론으로, 소프트웨어 보안의 모범 사례를 소프트웨어 개발 생명주기(SDLC)의 각 단계에 통합한 것이다. 요구사항, 설계, 코드, 테스트 등 단계마다 보안 점검 활동을 넣는다.","choices":[{"verdict":"오답","why":"CLASP는 SDLC 초기 단계에서 보안을 강화하기 위해 개발된 활동 중심·역할 기반의 보안 방법론이다."},{"verdict":"오답","why":"CWE(Common Weakness Enumeration)는 소프트웨어 보안 약점의 종류를 정리한 목록이지 개발 방법론이 아니다."},{"verdict":"오답","why":"PIMS는 개인정보보호 관리체계(인증)로, 소프트웨어 개발 보안 방법론이 아니다."},{"verdict":"정답","why":"SW 보안의 모범 사례를 SDLC에 통합한 실무 검증 개발 보안 방법론은 Seven Touchpoints다."}],"keywords":[{"term":"Seven Touchpoints","desc":"SW 보안 모범 사례를 SDLC에 통합한 개발 보안 방법론"},{"term":"CLASP","desc":"SDLC 초기 단계 보안 강화를 위한 활동 중심·역할 기반 방법론"},{"term":"MS SDL","desc":"마이크로소프트가 만든 보안 강화 개발 생명주기 방법론"}],"memo":"'모범 사례를 SDLC에 통합' = Seven Touchpoints, 'SDLC 초기 단계' = CLASP."}},{"id":"written-2020-3-100","no":100,"unit":"정보시스템 구축 관리","q":"다음 LAN의 네트워크 토폴로지는?\n<img src=\"data/img/eip_written_20200822_100.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["버스형","성형","링형","그물형"],"ans":1,"rate":93,"wiki":[{"title":"네트워크 토폴로지","url":"https://itwiki.kr/w/네트워크 토폴로지"}],"exp":{"concept":"네트워크 토폴로지는 장치들을 연결하는 모양이다. 그림은 가로로 뻗은 하나의 공통 케이블(버스)에 스테이션 1~5가 각각 매달려 있고 데이터가 양방향으로 흐르므로 버스형이다. 버스 정류장들이 하나의 도로에 늘어선 모습과 같다.","choices":[{"verdict":"정답","why":"하나의 공통 전송 회선에 모든 스테이션이 연결되어 있으므로 버스형이다."},{"verdict":"오답","why":"성형(Star)은 중앙 장치(허브 등)에 모든 노드가 방사형으로 연결된 구조다."},{"verdict":"오답","why":"링형(Ring)은 노드들이 원형 고리로 이어져 데이터가 한 방향 또는 양방향으로 순환하는 구조다."},{"verdict":"오답","why":"그물형(Mesh)은 모든 노드가 서로 직접 연결된 구조로, 노드가 n개면 회선 수는 n(n-1)/2 개다."}],"keywords":[{"term":"버스형","desc":"하나의 통신 회선에 여러 노드 연결, 설치 쉬움, 회선 고장 시 전체 영향"},{"term":"성형","desc":"중앙 장치 중심의 방사형 연결, 중앙 장치 고장 시 전체 마비"},{"term":"그물형","desc":"모든 노드를 서로 연결, 신뢰성 높고 회선 수 n(n-1)/2"}],"memo":"한 줄 케이블이면 버스형, 가운데 장치가 있으면 성형, 닫힌 고리면 링형."}}]};